# GAP-12: Auth endpoint rate limiting — 2026-06-13
import threading as _threading, collections as _collections
_rl_lock = _threading.Lock()
_rl_windows = _collections.defaultdict(list)
_RL_WINDOW, _RL_MAX = 60, 10

def _rate_limit_check(ip, endpoint):
    import time as _time
    key = f'{ip}:{endpoint}'
    now = _time.time()
    with _rl_lock:
        w = _rl_windows[key]
        w[:] = [t for t in w if now - t < _RL_WINDOW]
        if len(w) >= _RL_MAX:
            return False
        w.append(now)
    return True


# GAP-09: HTTP security headers — 2026-06-13
_SECURITY_HEADERS = {
    'Strict-Transport-Security': 'max-age=31536000; includeSubDomains',
    'X-Frame-Options': 'DENY',
    'X-Content-Type-Options': 'nosniff',
    'Referrer-Policy': 'strict-origin-when-cross-origin',
    'Content-Security-Policy': (
        "default-src 'self'; "
        "script-src 'self' 'unsafe-inline'; "
        "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; "
        "font-src 'self' https://fonts.gstatic.com data:; "
        "img-src 'self' data: blob:"
    ),
}

def _send_security_headers(handler):
    if getattr(handler, "_sec_headers_sent", False):
        return
    handler._sec_headers_sent = True
    for k, v in _SECURITY_HEADERS.items():
        handler.send_header(k, v)

