def _populate_env_from_vault():
    """At startup, pull secrets from the encrypted vault and seed os.environ
    (setdefault so EnvironmentFile / shell exports still win if someone sets them).
    Fail-safe: if the vault is unreachable, fall through to per-call defaults."""
    import sys as _sys
    _sys.path.insert(0, '/usr/sap/sap_skills')
    try:
        import vault_manager as _v
        _mp = open('/usr/sap/sap_skills/.vault_key').read().strip()
    except Exception:
        return
    def _pull(env_key, vault_key, field):
        try:
            entry = _v.get_entry(_mp, vault_key)
            if entry and field in entry and entry[field]:
                os.environ.setdefault(env_key, entry[field])
        except Exception:
            pass
    _pull('GCS_EXPLORER_PASSWORD', 'gcs_explorer_auth', 'password')
    _pull('POLARIS_GCS_CLIENT_ID',     'polaris_gcs',   'client_id')
    _pull('POLARIS_GCS_CLIENT_SECRET', 'polaris_gcs',   'client_secret')
    _pull('POLARIS_AZURE_CLIENT_ID',     'polaris_azure', 'client_id')
    _pull('POLARIS_AZURE_CLIENT_SECRET', 'polaris_azure', 'client_secret')
    _pull('POLARIS_AWS_CLIENT_ID',     'polaris_aws', 'client_id')
    _pull('POLARIS_AWS_CLIENT_SECRET', 'polaris_aws', 'client_secret')
    _pull('AZURE_STORAGE_ACCOUNT', 'azure_storage_ts', 'account_name')
    _pull('AWS_ACCESS_KEY_ID',     'aws_storage_s3',   'access_key_id')
    _pull('AWS_SECRET_ACCESS_KEY', 'aws_storage_s3',   'secret_access_key')
    _pull('AWS_REGION',            'aws_storage_s3',   'region')
    _pull('AZURE_STORAGE_KEY',     'azure_storage_ts', 'account_key')
    _pull('AZURE_STORAGE_CONTAINER','azure_storage_ts', 'container')
    _pull('AZURE_STORAGE_PREFIX',  'azure_storage_ts', 'base_prefix')

_populate_env_from_vault()

# ── AWS S3 singletons (boto3 for listing/regions, PyArrow for parquet) ───────
_AWS_CREDS_CACHE = {'k': None, 's': None}
_AWS_BOTO_CACHE  = {'client': None, 'key': None}
_AWS_FS_CACHE_R  = {}   # region -> S3FileSystem
_AWS_BKT_REGION  = {}   # bucket  -> region

def _aws_creds():
    if _AWS_CREDS_CACHE['k'] is not None: return _AWS_CREDS_CACHE['k'], _AWS_CREDS_CACHE['s']
    import os as _o; _k=_o.environ.get('AWS_ACCESS_KEY_ID',''); _s=_o.environ.get('AWS_SECRET_ACCESS_KEY','')
    if not _k:
        try:
            import sys as _sy
            if '/usr/sap/sap_skills' not in _sy.path: _sy.path.insert(0,'/usr/sap/sap_skills')
            import vault_manager as _vm
            _ent=_vm.get_entry(open('/usr/sap/sap_skills/.vault_key').read().strip(),'aws_storage_s3') or {}
            _k=_ent.get('access_key_id',''); _s=_ent.get('secret_access_key','')
        except: pass
    _AWS_CREDS_CACHE['k']=_k; _AWS_CREDS_CACHE['s']=_s
    return _k,_s

def _get_boto3_s3():
    _k,_s=_aws_creds()
    if _AWS_BOTO_CACHE['client'] is None or _AWS_BOTO_CACHE['key']!=_k:
        import boto3 as _b3
        _AWS_BOTO_CACHE['client']=_b3.client('s3',aws_access_key_id=_k,aws_secret_access_key=_s,region_name='us-east-1')
        _AWS_BOTO_CACHE['key']=_k
    return _AWS_BOTO_CACHE['client']

def _get_aws_fs():
    return _get_aws_fs_for_region('us-east-1')

def _get_aws_fs_for_region(_reg):
    if _reg not in _AWS_FS_CACHE_R:
        import pyarrow.fs as _pf
        _k,_s=_aws_creds()
        _AWS_FS_CACHE_R[_reg]=_pf.S3FileSystem(access_key=_k,secret_key=_s,region=_reg)
    return _AWS_FS_CACHE_R[_reg]

def _get_aws_bucket_region(_bkt):
    if _bkt in _AWS_BKT_REGION: return _AWS_BKT_REGION[_bkt]
    try:
        _loc=_get_boto3_s3().get_bucket_location(Bucket=_bkt)
        _r=_loc.get('LocationConstraint') or 'us-east-1'
    except: _r='us-east-1'
    _AWS_BKT_REGION[_bkt]=_r; return _r

# ── Azure filesystem singleton (avoids per-request thread-pool creation) ─────
_AZ_FS_CACHE = {'fs': None, 'acc': None}
def _get_az_fs():
    import os as _ozf, pyarrow.fs as _pf
    _a = _ozf.environ.get('AZURE_STORAGE_ACCOUNT', '')
    _k = _ozf.environ.get('AZURE_STORAGE_KEY', '')
    if _AZ_FS_CACHE['fs'] is None or _AZ_FS_CACHE['acc'] != _a:
        _AZ_FS_CACHE['fs'] = _pf.AzureFileSystem(account_name=_a, account_key=_k)
        _AZ_FS_CACHE['acc'] = _a
    return _AZ_FS_CACHE['fs']


