# Phase 2B: in-memory dict + DB write-through. On startup we hydrate from DB
# so a `systemctl restart gcs-explorer` doesn't log everyone out.
active_sessions = {}

# Phase 4B + asset migration: DB-backed serving for any /sap_skills/* asset
# (HTML, MD, JSON, SQL, images, downloads) with a small TTL cache so hot
# assets are served from RAM. portal-edit writes go to DB; FS fallback
# below in _do_GET keeps the portal alive if DB is unreachable for any path
# still mirrored on disk.
_doc_cache: dict = {}        # path -> (body_bytes, content_type, version, fetched_at)
_DOC_CACHE_TTL_S = 30        # seconds


def _doc_cache_get(path: str):
    """Return cached (body, content_type) for an asset if cache is fresh."""
    entry = _doc_cache.get(path)
    if not entry:
        return None
    body, ct, _ver, fetched_at = entry
    if (time.time() - fetched_at) > _DOC_CACHE_TTL_S:
        return None
    return body, ct


def _doc_cache_put(path: str, body: bytes, content_type: str, version: int) -> None:
    _doc_cache[path] = (body, content_type, version, time.time())


def _doc_cache_clear(*_unused) -> None:
    """SIGUSR1 handler — portal-edit signals us so saves are visible immediately
    rather than waiting up to _DOC_CACHE_TTL_S. Safe to call from any thread/sig
    context: dict.clear() is atomic in CPython."""
    _doc_cache.clear()
    print("doc_pages: cache cleared (SIGUSR1)", flush=True)


import signal as _signal
try:
    _signal.signal(_signal.SIGUSR1, _doc_cache_clear)
except Exception as _e:
    print(f"doc_pages: SIGUSR1 handler not installed: {_e}", flush=True)


def _inject_pdf_button(body: bytes, ct: str, parsed_path: str) -> bytes:
    """Inject a floating 'Download PDF' button + print CSS into HTML doc pages.

    Active only for text/html responses on /sap_skills/docs/*.html. The button
    triggers window.print(); the user picks 'Save as PDF' in the print dialog.
    Print output is marked 'Confidential - Fivetran Internal Use Only' via
    @page running header/footer + a top-of-body banner fallback + a subtle
    diagonal watermark.
    """
    try:
        if not (ct or "").lower().startswith("text/html"):
            return body
        # Restrict the PDF button + confidential markings to actual documentation pages.
        # That means filenames ending in _Documentation.html or _Guide.html under /sap_skills/docs/.
        # Cockpits, admin UIs, and other live pages don't get the button.
        _lp = parsed_path.lower()
        # Match _Documentation.html / _Guide.html and their translated variants
        # _Documentation_<lang>.html / _Guide_<lang>.html for the supported languages.
        _doc_suffixes = (
            "_documentation.html", "_guide.html",
            "_documentation_es.html", "_documentation_pt.html",
            "_documentation_it.html", "_documentation_nl.html",
            "_documentation_de.html",
            "_guide_es.html", "_guide_pt.html", "_guide_it.html",
            "_guide_nl.html", "_guide_de.html",
        )
        if not (parsed_path.startswith("/sap_skills/docs/") and _lp.endswith(_doc_suffixes)):
            return body
        html = body.decode("utf-8", errors="replace")
        if "id=\"pdf-download-btn\"" in html:
            return body
        style_block = (
            "\n<style id=\"pdf-download-style\">\n"
            "@media screen {\n"
            "  #pdf-download-btn {\n"
            "    position: fixed; bottom: 24px; right: 24px; z-index: 9999;\n"
            "    background: #0073FF; color: #fff; border: none;\n"
            "    padding: 10px 18px; border-radius: 8px;\n"
            "    font: 600 13px/1.2 -apple-system, Segoe UI, sans-serif;\n"
            "    cursor: pointer; box-shadow: 0 4px 14px rgba(0,0,0,0.18);\n"
            "    display: inline-flex; align-items: center; gap: 8px;\n"
            "  }\n"
            "  #pdf-download-btn:hover { background: #005cd9; box-shadow: 0 6px 18px rgba(0,0,0,0.22); }\n"
            "  #pdf-download-btn:active { transform: translateY(1px); }\n"
            "  #pdf-confidential-banner, #pdf-confidential-watermark { display: none !important; }\n"
            "}\n"
            "@media print {\n"
            "  #pdf-download-btn, #pdf-download-style,\n"
            "  #portal-user, .back-link, .sidebar, .nav, .nav-bar, .navbar,\n"
            "  .top-bar, header.top-bar { display: none !important; }\n"
            "  /* Fixed headers (e.g. OTC/P2P/MRP/PP fixed-top) -> flow normally so they don't repeat per page or hide content */\n"
            "  .fixed-top { position: static !important; box-shadow: none !important; }\n"
            "  /* Zero the bare-div spacers that compensate for fixed headers on screen */\n"
            "  body > div[style*=\"height:\"][style*=\"px\"]:empty { height: 0 !important; min-height: 0 !important; padding: 0 !important; margin: 0 !important; }\n"
            "  body { background: #fff !important; padding: 0 !important; position: relative; }\n"
            "  .container, .content, main, article { max-width: 100% !important; padding: 0 !important; margin: 0 !important; box-shadow: none !important; }\n"
            "  a { color: #000 !important; text-decoration: underline; }\n"
            "  pre, code { white-space: pre-wrap !important; word-wrap: break-word !important; }\n"
            "  table { page-break-inside: auto; }\n"
            "  tr { page-break-inside: avoid; page-break-after: auto; }\n"
            "  h1, h2, h3 { page-break-after: avoid; }\n"
            "  /* Confidential banner at top of every printed copy */\n"
            "  #pdf-confidential-banner {\n"
            "    display: block !important;\n"
            "    text-align: center;\n"
            "    color: #b91c1c;\n"
            "    font: 600 10pt/1.3 -apple-system, Segoe UI, sans-serif;\n"
            "    letter-spacing: 0.04em;\n"
            "    border-top: 1px solid #b91c1c;\n"
            "    border-bottom: 1px solid #b91c1c;\n"
            "    padding: 4px 0;\n"
            "    margin: 0 0 8mm 0;\n"
            "  }\n"
            "  /* Diagonal watermark on every page */\n"
            "  #pdf-confidential-watermark {\n"
            "    display: block !important;\n"
            "    position: fixed;\n"
            "    top: 50%; left: 50%;\n"
            "    transform: translate(-50%, -50%) rotate(-30deg);\n"
            "    font: 800 70pt/1 -apple-system, Segoe UI, sans-serif;\n"
            "    color: rgba(185, 28, 28, 0.07);\n"
            "    z-index: -1;\n"
            "    pointer-events: none;\n"
            "    white-space: nowrap;\n"
            "  }\n"
            "  /* Preserve background colors of colored boxes / watermark */\n"
            "  *, *::before, *::after { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }\n"
            "  /* Diagrams: allow wrap, rotate arrows, shrink boxes */\n"
            "  .flow-container { flex-wrap: wrap !important; justify-content: center !important; row-gap: 12px !important; column-gap: 8px !important; padding: 12px 0 !important; overflow: visible !important; }\n"
            "  .flow-arrow { transform: rotate(90deg) !important; padding: 0 4px !important; font-size: 1.1rem !important; }\n"
            "  .flow-step { min-width: 90px !important; flex: 0 0 auto !important; }\n"
            "  .flow-box { font-size: 9pt !important; padding: 8px 6px !important; box-shadow: none !important; }\n"
            "  .flow-sub { font-size: 7pt !important; }\n"
            "  /* Generic image/svg containment */\n"
            "  img, svg { max-width: 100% !important; height: auto !important; }\n"
            "  /* Cards / sections shouldn't split if reasonable */\n"
            "  .card, .section, .info-box { page-break-inside: avoid; }\n"
            "  /* Running header/footer (Chrome/Edge/Safari) */\n"
            "  @page {\n"
            "    size: A4;\n"
            "    margin: 18mm 14mm 20mm 14mm;\n"
            "    @top-right { content: \"Confidential - Fivetran Internal Use Only\"; font: 600 9pt/1 sans-serif; color: #b91c1c; }\n"
            "    @bottom-center { content: \"Page \" counter(page) \" of \" counter(pages); font: 9pt/1 sans-serif; color: #6b7280; }\n"
            "    @bottom-right { content: \"sapidesecc8.fivetran-internal-sales.com\"; font: 8pt/1 sans-serif; color: #9ca3af; }\n"
            "  }\n"
            "}\n"
            "</style>\n"
        )
        button_block = (
            "\n<button id=\"pdf-download-btn\" type=\"button\" "
            "onclick=\"(function(){var u=window.location.pathname+'?print='+Date.now();window.open(u,'_blank');})()\" "
            "title=\"Open a fresh copy and Save as PDF (always reflects the latest content)\">"
            "<svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" "
            "stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">"
            "<path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/>"
            "<line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"/></svg>"
            "<span>Download PDF</span></button>\n"
            "<div id=\"pdf-confidential-banner\">CONFIDENTIAL \u2014 FIVETRAN INTERNAL USE ONLY</div>\n"
            "<div id=\"pdf-confidential-watermark\">FIVETRAN CONFIDENTIAL</div>\n"
            "<script id=\"pdf-auto-print\">"
            "(function(){if((location.search||'').indexOf('print=')>=0){window.addEventListener('load',function(){setTimeout(function(){try{window.print();}catch(e){}},500);});}})();"
            "</script>\n"
        )
        if "</head>" in html:
            html = html.replace("</head>", style_block + "</head>", 1)
        else:
            html = style_block + html
        if "</body>" in html:
            html = html.replace("</body>", button_block + "</body>", 1)
        else:
            html = html + button_block
        return html.encode("utf-8")
    except Exception as _e:
        print(f"  inject_pdf_button failed for {parsed_path}: {_e}")
        return body


def _serve_doc_from_db(parsed_path: str, bypass_cache: bool = False):
    """Try to serve /sap_skills/<anything> from doc_pages.

    Returns (body_bytes, content_type) tuple, or (None, None) to fall
    through to the filesystem. Handles both text rows (`content`) and
    binary rows (`body_bytes`). DB errors fall through silently.

    `bypass_cache=True` skips the in-process TTL cache so the response
    always reflects the latest DB row (used for ?print= PDF generation).
    """
    if not bypass_cache:
        cached = _doc_cache_get(parsed_path)
        if cached is not None:
            return cached
    try:
        sys.path.insert(0, "/usr/sap/sap_skills")
        import db_manager as _db_doc
        row = _db_doc.doc_pages_get(parsed_path)
    except Exception as e:
        print(f"doc_pages: DB lookup failed for {parsed_path}: {e}", flush=True)
        return None, None
    if not row:
        return None, None
    ct = row.get("content_type") or "application/octet-stream"
    if row.get("body_bytes") is not None:
        body = bytes(row["body_bytes"])
    else:
        body = (row.get("content") or "").encode("utf-8")
    body = _inject_pdf_button(body, ct, parsed_path)
    _doc_cache_put(parsed_path, body, ct, row.get("version") or 0)
    return body, ct

# Session expiry policy (enforced server-side on every _require_session call)
IDLE_TIMEOUT_SECONDS = 12 * 3600         # 12 h of inactivity -> auto-logout
ABSOLUTE_TIMEOUT_SECONDS = 16 * 3600     # 16 h absolute cap (matches cookie Max-Age)

# Phase 2B: DB write-through for sessions. All `_db_session_*_safe` helpers are
# best-effort — they never raise, so a DB outage degrades to current-process-
# only sessions (lost on next restart, just like before Phase 2B).
try:
    sys.path.insert(0, "/usr/sap/sap_skills")
    import db_manager as _db_sess
    _DB_SESS_OK = True
except Exception:
    _db_sess = None
    _DB_SESS_OK = False


def _db_session_create_safe(token, email, idle_exp, abs_exp, ip):
    if not _DB_SESS_OK:
        return False
    try:
        _db_sess.sessions_create(token=token, email=email,
                                 idle_expires_at=idle_exp,
                                 absolute_expires_at=abs_exp,
                                 ip=ip)
        return True
    except Exception as e:
        print(f"sessions: DB create failed: {e}", flush=True)
        return False


def _db_session_touch_safe(token, last_seen, idle_exp):
    if not _DB_SESS_OK:
        return False
    try:
        return _db_sess.sessions_touch(token,
                                       last_seen_at=last_seen,
                                       idle_expires_at=idle_exp)
    except Exception as e:
        print(f"sessions: DB touch failed: {e}", flush=True)
        return False


def _db_session_get_safe(token):
    if not _DB_SESS_OK:
        return None
    try:
        return _db_sess.sessions_get(token)
    except Exception as e:
        print(f"sessions: DB get failed: {e}", flush=True)
        return None


def _db_session_delete_safe(token):
    if not _DB_SESS_OK or not token:
        return False
    try:
        return _db_sess.sessions_delete(token)
    except Exception as e:
        print(f"sessions: DB delete failed: {e}", flush=True)
        return False


def _db_session_delete_for_email_safe(email):
    if not _DB_SESS_OK or not email:
        return 0
    try:
        return _db_sess.sessions_delete_for_email(email)
    except Exception as e:
        print(f"sessions: DB delete_for_email failed: {e}", flush=True)
        return 0


def _hydrate_sessions_from_db():
    """Phase 2B startup: pull active sessions from DB into active_sessions so
    a service restart preserves user logins (transparent restart). Best-effort:
    if the DB is unreachable, we log and start empty — matches pre-2B behavior."""
    if not _DB_SESS_OK:
        return 0
    try:
        rows = _db_sess.sessions_load_active()
    except Exception as e:
        print(f"sessions: hydrate skipped (DB unavailable): {e}", flush=True)
        return 0
    n = 0
    for r in rows:
        active_sessions[r["token"]] = {
            "email":     r["email"],
            "created":   r["created_at"],
            "last_seen": r["last_seen_at"],
            "ip":        (str(r["ip"]).split("/")[0] if r.get("ip") is not None else None),
        }
        n += 1
    print(f"sessions: hydrated {n} from DB", flush=True)
    return n


_hydrate_sessions_from_db()

