def _evict_user_sessions(email):
    """Remove every active session belonging to the given email. Used by
    suspend / set_role demote / delete so the change takes effect immediately."""
    if not email:
        return 0
    e = email.strip().lower()
    n = 0
    for tok in list(active_sessions.keys()):
        s = active_sessions.get(tok)
        if s and s.get("email", "").strip().lower() == e:
            active_sessions.pop(tok, None)
            n += 1
    _db_session_delete_for_email_safe(e)
    return n


def _now_utc():
    return datetime.now(timezone.utc)


def _to_aware(dt):
    """Coerce a possibly-naive datetime (from legacy in-memory sessions) into
    a tz-aware UTC datetime so arithmetic is consistent with hydrated rows."""
    if dt is None:
        return None
    if dt.tzinfo is None:
        return dt.replace(tzinfo=timezone.utc)
    return dt


def _session_lookup(token):
    """Return session dict if still valid; else None. Evicts expired tokens in place.
    Phase 2B: on cache miss, falls back to DB so a freshly-restarted process
    still recognizes a valid cookie."""
    if not token:
        return None
    sess = active_sessions.get(token)
    if not sess:
        # Phase 2B fallback — DB lookup re-hydrates a single session
        row = _db_session_get_safe(token)
        if not row:
            return None
        sess = {"email":     row["email"],
                "created":   row["created_at"],
                "last_seen": row["last_seen_at"]}
        active_sessions[token] = sess
    now = _now_utc()
    created = _to_aware(sess.get("created"))
    last = _to_aware(sess.get("last_seen") or created)
    if created and (now - created).total_seconds() > ABSOLUTE_TIMEOUT_SECONDS:
        active_sessions.pop(token, None)
        _db_session_delete_safe(token)
        return None
    if last and (now - last).total_seconds() > IDLE_TIMEOUT_SECONDS:
        active_sessions.pop(token, None)
        _db_session_delete_safe(token)
        return None
    sess["last_seen"] = now
    _db_session_touch_safe(token, now,
                           now + timedelta(seconds=IDLE_TIMEOUT_SECONDS))
    return sess

# NOTE: real authentication lives in portal_auth.py (Argon2id, PBKDF2-HMAC-SHA256
# @480k iters, per-user salts) + Google OAuth. The former module-level SHA-256
# _hash_password/PASSWORD_HASH gate was dead code (referenced nowhere) and has
# been removed so it can never be mistakenly wired into an auth path.


# ----------------------------- _local_su helper ------------------------------
# Phase -1 (2026-04-25). The portal app runs as the unprivileged `portal`
# OS user, so it can no longer `su -` to abaadm/oraaba/etc. We pivot via
# ssh-to-localhost: portal's pubkey is in those users' authorized_keys.
# The remote shell ssh opens IS the user's shell (login shell), so the
# call semantics match what `su - <user> -c "<cmd>"` did before.
#
# Local users today: abaadm (SAP ECC) + oraaba (Oracle ABA), both on
# sapidesecc8. Anything else (s4hadm, bwhadm, postgres@saphvrhub, etc.)
# is *remote* and goes through the existing `ssh root@<host>` chain
# unchanged — that path's `su -` is invoked as remote root and still works.
def _local_su(user, cmd_str):
    """Return an argv list that runs cmd_str as <user> via ssh-to-localhost.
    Replaces ['su', '-', user, '-c', cmd_str] for Phase -1."""
    return ["ssh",
            "-o", "BatchMode=yes",
            "-o", "StrictHostKeyChecking=no",
            "-o", "ConnectTimeout=5",
            f"{user}@localhost",
            cmd_str]

def create_session(email, ip=None):
    token = secrets.token_hex(32)
    now = _now_utc()
    idle_exp = now + timedelta(seconds=IDLE_TIMEOUT_SECONDS)
    abs_exp  = now + timedelta(seconds=ABSOLUTE_TIMEOUT_SECONDS)
    active_sessions[token] = {"email": email, "created": now, "last_seen": now, "ip": ip}
    _db_session_create_safe(token, email, idle_exp, abs_exp, ip)
    # Resolve geo synchronously on every new session (cache-first, ~200ms on miss)
    _geo_short = ""
    _geo_full  = ""
    if ip:
        try:
            import db_manager as _dbm_geo
            _geo_short = _dbm_geo.geo_short(ip)
            _geo_full  = _dbm_geo.geo_full(ip)
        except Exception:
            pass
    _geo_suffix = f"  [{_geo_full}]" if _geo_full else ""
    print(f"  Login: {email}  ip={ip}{_geo_suffix}", flush=True)
    return token

def get_session(cookie_header):
    if not cookie_header:
        return None
    cookies = http.cookies.SimpleCookie()
    try:
        cookies.load(cookie_header)
    except Exception:
        return None
    morsel = cookies.get("session")
    if not morsel:
        return None
    return _session_lookup(morsel.value)

