# Global state
gcs_client = None
_server_start_time = time.time()


# ── DuckDB Subprocess Worker ──────────────────────────────────────────────────
# DuckDB's C extension holds the Python GIL during network I/O (ATTACH ICEBERG,
# iceberg_scan over S3). This freezes ALL Python threads — including the HTTP
# server. Moving DuckDB into a child process isolates its GIL from the server.
# The main process communicates via multiprocessing.Queue (command/response).

def _duckdb_worker(cmd_q, resp_q):
    """Subprocess entry point. Owns the DuckDB connection — no other process touches it."""
    import signal
    signal.signal(signal.SIGTERM, lambda *_: sys.exit(0))

    import duckdb as _ddb
    import pyarrow as _pa
    import pyarrow.ipc as _ipc

    db = None
    arrow_tables = {}  # name -> pyarrow.Table (prevent GC so DuckDB references stay valid)

    while True:
        try:
            cmd = cmd_q.get(timeout=5)
        except Exception:
            continue
        cmd_id = cmd.get("id", "")
        cmd_name = cmd.get("cmd", "")
        args = cmd.get("args", {})
        try:
            if cmd_name == "init":
                if not os.environ.get("HOME"):
                    os.environ["HOME"] = "/root"
                db = _ddb.connect(":memory:")
                db.execute(f"SET home_directory='{os.environ['HOME']}';")
                db.execute("INSTALL httpfs; LOAD httpfs;")
                db.execute("INSTALL iceberg; LOAD iceberg;")
                db.execute("INSTALL azure; LOAD azure;")
                db.execute("SET azure_transport_option_type='curl';")
                resp_q.put({"id": cmd_id, "status": "ok", "result": {}})

            elif cmd_name == "exec_sql":
                q = args["query"]
                r = db.execute(q)
                cols = [desc[0] for desc in r.description] if r.description else []
                data = r.fetchall()
                # Convert to strings for safe serialization
                safe = []
                for row in data:
                    safe.append([str(v) if v is not None else "" for v in row])
                resp_q.put({"id": cmd_id, "status": "ok", "result": {"cols": cols, "data": safe}})

            elif cmd_name == "exec_multi":
                # Execute multiple SQL statements (no result needed)
                for stmt in args["statements"]:
                    db.execute(stmt)
                resp_q.put({"id": cmd_id, "status": "ok", "result": {}})

            elif cmd_name == "register_table":
                name = args["name"]
                ipc_bytes = args["ipc_bytes"]
                reader = _ipc.open_stream(ipc_bytes)
                table = reader.read_all()
                arrow_tables[name] = table
                db.register(name, table)
                resp_q.put({"id": cmd_id, "status": "ok", "result": {}})

            elif cmd_name == "unregister_table":
                name = args["name"]
                try:
                    db.unregister(name)
                except Exception:
                    pass
                arrow_tables.pop(name, None)
                resp_q.put({"id": cmd_id, "status": "ok", "result": {}})

            elif cmd_name == "interrupt":
                try:
                    db.interrupt()
                except Exception:
                    pass
                resp_q.put({"id": cmd_id, "status": "ok", "result": {}})

            elif cmd_name == "shutdown":
                resp_q.put({"id": cmd_id, "status": "ok", "result": {}})
                break

            else:
                resp_q.put({"id": cmd_id, "status": "error", "error": f"Unknown command: {cmd_name}"})

        except Exception as e:
            resp_q.put({"id": cmd_id, "status": "error", "error": str(e)})


def _serialize_arrow_table(table):
    """Serialize a PyArrow table to IPC bytes for cross-process transfer."""
    import pyarrow as _pa
    import pyarrow.ipc as _ipc
    sink = _pa.BufferOutputStream()
    writer = _ipc.new_stream(sink, table.schema)
    writer.write_table(table)
    writer.close()
    return sink.getvalue().to_pybytes()


class DuckDBWorker:
    """Main-process client for the DuckDB subprocess. Thread-safe — multiple HTTP
    handler threads can call send_command concurrently; commands are serialized
    in the subprocess (one at a time via Queue).

    Phase 2 of per-user-Polaris (2026-04-29): each worker is a per-user instance
    owned by `DuckDBWorkerManager`. State that used to live in module-level
    dicts (polaris_catalogs, loaded_tables, _s3_vended_cache) now lives on the
    instance so different users' Polaris scopes / loaded tables / vended S3
    creds can't bleed across each other.
    """

    def __init__(self, owner_email: str = ""):
        self._cmd_q = None
        self._resp_q = None
        self._proc = None
        self._pending = {}  # cmd_id -> {"event": Event, "result": dict}
        self._reader_thread = None
        # Per-user state
        self.owner_email = owner_email
        self.polaris_catalogs: dict = {}        # alias -> {endpoint, catalog, client_id, client_secret}
        self.loaded_tables: "OrderedDict" = OrderedDict()
        self._s3_vended_cache: dict = {}        # alias -> {token, expires, s3_creds}
        self.last_used: float = time.time()

    def start(self):
        """Spawn (or respawn) the subprocess and initialize DuckDB."""
        self._cmd_q = multiprocessing.Queue()
        self._resp_q = multiprocessing.Queue()
        self._proc = multiprocessing.Process(
            target=_duckdb_worker,
            args=(self._cmd_q, self._resp_q),
            daemon=True
        )
        self._proc.start()
        # Background thread dispatches responses to waiters
        self._reader_thread = threading.Thread(target=self._response_reader, daemon=True)
        self._reader_thread.start()
        # Initialize DuckDB in the subprocess
        self.send_command("init", {}, timeout=30)
        print("  DuckDB extensions: httpfs, iceberg, azure loaded (azure transport: curl)")

    def send_command(self, cmd, args, timeout=60):
        """Send a command and block until response or timeout.
        On timeout, kills the subprocess and respawns."""
        cmd_id = str(uuid.uuid4())
        event = threading.Event()
        self._pending[cmd_id] = {"event": event, "result": None}
        self._cmd_q.put({"id": cmd_id, "cmd": cmd, "args": args})
        if not event.wait(timeout=timeout):
            # Subprocess is hung — kill and respawn
            self._kill_and_respawn()
            self._pending.pop(cmd_id, None)
            raise Exception(f"DuckDB operation timed out after {timeout}s — worker restarted.")
        result = self._pending.pop(cmd_id, {}).get("result", {})
        if result.get("status") == "error":
            raise Exception(result.get("error", "Unknown error"))
        return result.get("result")

    def _response_reader(self):
        """Background thread that reads responses and wakes waiting callers."""
        while True:
            try:
                resp = self._resp_q.get(timeout=2)
            except Exception:
                if self._proc and not self._proc.is_alive():
                    # Worker died unexpectedly — wake all waiters
                    for entry in self._pending.values():
                        entry["result"] = {"status": "error", "error": "DuckDB worker crashed"}
                        entry["event"].set()
                    self._pending.clear()
                continue
            pending = self._pending.get(resp.get("id"))
            if pending:
                pending["result"] = resp
                pending["event"].set()

    def _kill_and_respawn(self):
        """Kill a hung subprocess and start a fresh one. Per-user worker —
        only this user's state is wiped."""
        owner = f" for {self.owner_email}" if self.owner_email else ""
        print(f"  WORKER: DuckDB subprocess{owner} timed out — killing and respawning...")
        if self._proc and self._proc.is_alive():
            self._proc.kill()
            self._proc.join(timeout=5)
        # Wake all pending waiters with error
        for entry in self._pending.values():
            entry["result"] = {"status": "error", "error": "Worker restarted due to timeout"}
            entry["event"].set()
        self._pending.clear()
        # Clear THIS worker's main-process state (other users untouched)
        self.loaded_tables.clear()
        self.polaris_catalogs.clear()
        self._s3_vended_cache.clear()
        print(f"  WORKER: tables + catalogs lost{owner} — respawning...")
        self.start()

    def shutdown(self):
        """Clean shutdown — used by the manager when reaping idle / LRU workers."""
        try:
            self.send_command("shutdown", {}, timeout=5)
        except Exception:
            pass
        if self._proc and self._proc.is_alive():
            try:
                self._proc.terminate()
                self._proc.join(timeout=3)
                if self._proc.is_alive():
                    self._proc.kill()
                    self._proc.join(timeout=2)
            except Exception:
                pass
        self.polaris_catalogs.clear()
        self.loaded_tables.clear()
        self._s3_vended_cache.clear()


# ---------------------------------------------------------------------------
# DuckDBWorkerManager — per-user worker registry with LRU + idle reaping.
#
# Phase 2 of per-user-Polaris (2026-04-29). One DuckDB subprocess per logged-in
# user, lazily spawned on the first DuckDB-touching request.
#
# Lifecycle:
#   - spawn:   first /api/sql, /api/polaris/connect, /api/parquet, etc.
#   - destroy: explicit logout, session expire, idle >30 min, LRU at >10 active
#              workers or system memory >85%.
# ---------------------------------------------------------------------------

class DuckDBWorkerManager:
    MAX_WORKERS       = 10
    IDLE_TIMEOUT_S    = 30 * 60
    MEMORY_THRESHOLD  = 0.85
    REAPER_INTERVAL_S = 60

    def __init__(self):
        self._workers: dict[str, DuckDBWorker] = {}
        self._lock = threading.Lock()
        self._reaper_thread: threading.Thread | None = None

    def start_reaper(self):
        if self._reaper_thread and self._reaper_thread.is_alive():
            return
        self._reaper_thread = threading.Thread(
            target=self._reaper_loop, daemon=True, name="duckdb-reaper",
        )
        self._reaper_thread.start()

    def get_or_create(self, email: str) -> DuckDBWorker:
        if not email:
            raise RuntimeError("DuckDB worker requires an authenticated user")
        with self._lock:
            w = self._workers.get(email)
            if w is not None:
                w.last_used = time.time()
                return w
            self._evict_if_needed_locked()
            w = DuckDBWorker(owner_email=email)
            self._workers[email] = w
        try:
            w.start()
            print(f"  DuckDB worker spawned for {email} (pid {w._proc.pid})")
        except Exception:
            with self._lock:
                self._workers.pop(email, None)
            raise
        w.last_used = time.time()
        return w

    def get(self, email: str) -> DuckDBWorker | None:
        with self._lock:
            w = self._workers.get(email)
            if w:
                w.last_used = time.time()
            return w

    def kill(self, email: str) -> bool:
        with self._lock:
            w = self._workers.pop(email, None)
        if not w:
            return False
        try:
            w.shutdown()
        except Exception as e:
            print(f"  worker shutdown for {email} raised: {e}")
        return True

    def all_emails(self) -> list[str]:
        with self._lock:
            return list(self._workers.keys())

    def stats(self) -> list[dict]:
        with self._lock:
            return [
                {"email": e, "last_used": w.last_used,
                 "tables": len(w.loaded_tables),
                 "catalogs": len(w.polaris_catalogs)}
                for e, w in self._workers.items()
            ]

    def _evict_if_needed_locked(self):
        try:
            mem_pct = psutil.virtual_memory().percent / 100.0
        except Exception:
            mem_pct = 0
        # Evict LRU worker(s) until under both caps (count + memory).
        while self._workers and (
            len(self._workers) >= self.MAX_WORKERS or
            mem_pct >= self.MEMORY_THRESHOLD
        ):
            lru_email = min(self._workers, key=lambda e: self._workers[e].last_used)
            print(f"  DuckDB manager: LRU evict {lru_email} "
                  f"(workers={len(self._workers)}, mem={mem_pct*100:.0f}%)")
            w = self._workers.pop(lru_email)
            try:
                w.shutdown()
            except Exception:
                pass
            try:
                mem_pct = psutil.virtual_memory().percent / 100.0
            except Exception:
                break

    def _reaper_loop(self):
        while True:
            try:
                time.sleep(self.REAPER_INTERVAL_S)
                now = time.time()
                victims: dict[str, DuckDBWorker] = {}
                with self._lock:
                    for email, w in list(self._workers.items()):
                        if (now - w.last_used) > self.IDLE_TIMEOUT_S:
                            victims[email] = w
                            self._workers.pop(email, None)
                for email, w in victims.items():
                    print(f"  DuckDB manager: reaping idle {email} "
                          f"(idle {(now - w.last_used)/60:.1f} min)")
                    try:
                        w.shutdown()
                    except Exception:
                        pass
            except Exception as e:
                print(f"  DuckDB reaper error: {e}")


_worker_mgr = DuckDBWorkerManager()


def _get_worker() -> DuckDBWorker:
    """Return the calling user's DuckDB worker — spawn lazily on first touch."""
    email = _current_request_email()
    if not email:
        raise RuntimeError("DuckDB operations require an authenticated user")
    return _worker_mgr.get_or_create(email)


def _try_get_worker() -> DuckDBWorker | None:
    """Like _get_worker but returns None if the user doesn't have one yet
    (for read-only inspectors that shouldn't trigger a spawn)."""
    email = _current_request_email()
    if not email:
        return None
    return _worker_mgr.get(email)


# Compat shims for tooling that still expects these names. Module-level
# `polaris_catalogs` / `loaded_tables` are GONE — they're per-worker now.
current_bucket = BUCKET_NAME       # default browse bucket (still global)
MEMORY_THRESHOLD = 0.85            # used by per-worker _maybe_evict


def _save_state(bucket, prefix):
    """Persist last browsed bucket/prefix per user.

    DB row in `datalake_user_state` keyed by `_current_request_email()` is the
    sole source of truth for an authenticated request. The FS fallback file is
    only written when no email is available (e.g. startup probe). Writing the
    FS file from a request context used to leak one user's last location into
    the next user's first /api/init response (a fresh user with no DB row would
    fall back to whatever the last writer saved on disk).
    """
    email = _current_request_email()
    if email:
        try:
            from db_manager import connect as _connect
            with _connect() as _c, _c.cursor() as _cur:
                _cur.execute(
                    """INSERT INTO public.datalake_user_state (email, bucket, prefix, updated_at)
                       VALUES (%s, %s, %s, now())
                       ON CONFLICT (email) DO UPDATE SET
                         bucket = EXCLUDED.bucket,
                         prefix = EXCLUDED.prefix,
                         updated_at = now()""",
                    (email, bucket, prefix),
                )
        except Exception as _e:
            print(f"  _save_state DB upsert failed for {email}: {_e}")
        return
    # No authenticated user (rare — unauthenticated startup probe). Keep a
    # default in the FS file so the very first request after boot still has
    # something to load before the DB is reachable.
    try:
        with open(STATE_FILE, "w") as f:
            json.dump({"bucket": bucket, "prefix": prefix}, f)
    except Exception:
        pass


def _load_state():
    """Load last browsed bucket/prefix for the current user.

    Authenticated request → DB only (or None if no row yet). Never falls back
    to the shared FS file when an email is set, because the FS file holds
    whoever-wrote-last and would land a fresh user at someone else's spot.
    """
    email = _current_request_email()
    if email:
        try:
            from db_manager import connect as _connect
            with _connect() as _c, _c.cursor() as _cur:
                _cur.execute(
                    "SELECT bucket, prefix FROM public.datalake_user_state WHERE email=%s",
                    (email,),
                )
                _r = _cur.fetchone()
                if _r and (_r["bucket"] or _r["prefix"] is not None):
                    return {"bucket": _r["bucket"], "prefix": _r["prefix"]}
        except Exception as _e:
            print(f"  _load_state DB read failed for {email}: {_e}")
        # No row for this user — return None so caller uses BUCKET_NAME / "" defaults.
        return None
    # Unauthenticated context (startup probe etc.) — fall back to FS file if any.
    try:
        with open(STATE_FILE) as f:
            return json.load(f)
    except Exception:
        return None


def _maybe_evict(worker: DuckDBWorker | None = None):
    """Evict oldest loaded tables in the given worker (or caller's worker)
    until system memory usage drops below threshold."""
    w = worker or _try_get_worker()
    if w is None:
        return
    mem = psutil.virtual_memory()
    while mem.percent / 100.0 >= MEMORY_THRESHOLD and w.loaded_tables:
        name, meta = w.loaded_tables.popitem(last=False)
        try:
            w.send_command("unregister_table", {"name": name}, timeout=10)
        except Exception:
            pass
        mb = meta.get("nbytes", 0) / (1024 * 1024) if isinstance(meta, dict) else 0
        mem = psutil.virtual_memory()
        print(f"  Evicted table '{name}' (~{mb:.1f} MB) — memory now at {mem.percent:.0f}%")


def init_gcs():
    """Initialize GCS client using Application Default Credentials."""
    global gcs_client
    try:
        gcs_client = gcs_storage.Client()
        # Quick test
        bucket = gcs_client.bucket(BUCKET_NAME)
        bucket.reload()
        state = _load_state()
        return {
            "status": "ok",
            "message": f"Connected to gs://{BUCKET_NAME}",
            "last_bucket": state["bucket"] if state else BUCKET_NAME,
            "last_prefix": state["prefix"] if state else "",
        }
    except Exception as e:
        return {"status": "error", "message": str(e)}


# ----------------------- Phase I: per-user GCS client ------------------------
#
# `_request_local.email` is set by `_require_session` for every gated request.
# `_gcs()` returns the right client for the current request:
#
#   - bootstrap admins (Antonio, Richard) → shared module-level VM-SA client
#     (no behaviour change)
#   - everyone else → per-user client built from their stored Google refresh
#     token; raises NeedsGoogleAuth if they haven't done consent yet
#
# Each data-plane function catches NeedsGoogleAuth and returns a
# `google_auth_required` payload that the frontend turns into a redirect to
# `/auth/google/start`.

_request_local = threading.local()

class NeedsGoogleAuth(Exception):
    """Non-bootstrap user has no usable Google refresh token; consent needed."""
    pass


def _current_request_email():
    return getattr(_request_local, "email", "") or ""


def _gcs():
    """Return the right GCS client for the current request thread.

    Falls back to the shared VM-SA `gcs_client` whenever:
      - no request context is set (e.g. startup helpers, init_gcs's reload),
      - the user is a bootstrap admin,
      - the OAuth vault entry isn't configured yet (open-point: GCP setup
        pending), so existing flows keep working until that's done.
    """
    email = _current_request_email()
    if not email:
        return gcs_client
    if _portal_auth and email in _portal_auth.ADMIN_BOOTSTRAP_EMAILS:
        return gcs_client
    rt = _portal_auth.get_google_refresh_token(email) if _portal_auth else None
    if not rt:
        # No refresh token yet → if OAuth isn't even configured, gracefully
        # fall back to VM SA so the portal isn't bricked while we set up GCP.
        try:
            import google_oauth as _g_oauth
            if not _g_oauth.is_configured():
                return gcs_client
        except Exception:
            return gcs_client
        raise NeedsGoogleAuth()
    try:
        import google_oauth as _g_oauth
        from google.oauth2.credentials import Credentials as _GoogleCreds
        access_token = _g_oauth.refresh_access_token(rt)
        return gcs_storage.Client(credentials=_GoogleCreds(token=access_token))
    except NeedsGoogleAuth:
        raise
    except Exception as e:
        # Refresh token broken (revoked, expired, etc.) — clear it + force
        # the user back through consent. Side benefit: stale tokens auto-heal.
        try:
            if _portal_auth:
                _portal_auth.clear_google_refresh_token(email)
        except Exception:
            pass
        raise NeedsGoogleAuth(str(e))


def _google_auth_response():
    return {"status": "google_auth_required",
            "consent_url": "/auth/google/start",
            "message": "Please connect your Google account to access this datalake."}
# ---------------------- end Phase I per-user GCS client ----------------------


def list_buckets():
    """List all GCS buckets accessible to the authenticated account."""
    try:
        gcs = _gcs()
    except NeedsGoogleAuth:
        return _google_auth_response()
    try:
        buckets = []
        for b in gcs.list_buckets():
            buckets.append({"name": b.name})
        return {"status": "ok", "buckets": buckets}
    except Exception as e:
        return {"status": "error", "message": str(e)}


def init_duckdb():
    """Start the per-user worker manager's reaper. Workers are now lazily
    spawned per logged-in user (DuckDBWorkerManager.get_or_create), so there
    is no longer a global subprocess to start at boot."""
    _worker_mgr.start_reaper()


def _aws_region_from_endpoint(endpoint: str) -> str:
    """Extract the AWS region from a Polaris endpoint URL.
    e.g. https://pack-dictate.us-west-2.aws.polaris.fivetran.com/... -> us-west-2
    Falls back to 'us-east-1' if not found."""
    m = re.search(r'\.([a-z]+-(?:[a-z]+-)\d+)\.aws\.', endpoint)
    return m.group(1) if m else "us-east-1"


def connect_polaris(alias, endpoint, catalog, client_id, client_secret):
    """Connect to a Polaris Iceberg catalog in THE CALLER'S DuckDB worker."""
    if not alias or not endpoint or not catalog or not client_id or not client_secret:
        return {"status": "error", "message": "All fields are required"}
    safe_alias = alias.replace("-", "_").replace(" ", "_").lower()
    try:
        worker = _get_worker()
    except RuntimeError as e:
        return {"status": "error", "message": str(e)}
    # Skip if already connected with same catalog (in this user's worker)
    existing = worker.polaris_catalogs.get(safe_alias)
    if existing and existing.get("catalog") == catalog and existing.get("endpoint") == endpoint and existing.get("client_id") == client_id:
        print(f"  Catalog '{safe_alias}' already connected for {worker.owner_email}, skipping re-attach")
        return {"status": "ok", "alias": safe_alias, "message": f"Already connected: {safe_alias} ({catalog}). Query as: {safe_alias}.<namespace>.<table>"}
    secret_name = f"secret_{safe_alias}"
    oauth_uri = endpoint.rstrip("/") + "/v1/oauth/tokens"
    is_aws = ".aws." in endpoint
    aws_region = _aws_region_from_endpoint(endpoint) if is_aws else None
    attach_extra = f",\n                DEFAULT_REGION '{aws_region}'" if aws_region else ""
    try:
        # 65s timeout — ATTACH TYPE ICEBERG makes network calls that can hang.
        # If it hangs, send_command kills and respawns this user's subprocess.
        worker.send_command("exec_multi", {"statements": [
            f"DETACH DATABASE IF EXISTS {safe_alias};",
            f"DROP SECRET IF EXISTS {secret_name};",
            f"""CREATE SECRET {secret_name} (
                TYPE iceberg,
                CLIENT_ID '{client_id}',
                CLIENT_SECRET '{client_secret}',
                OAUTH2_SCOPE 'PRINCIPAL_ROLE:ALL',
                OAUTH2_SERVER_URI '{oauth_uri}'
            );""",
            f"""ATTACH '{catalog}' AS {safe_alias} (
                TYPE ICEBERG,
                ENDPOINT '{endpoint}',
                SECRET {secret_name}{attach_extra}
            );""",
        ]}, timeout=65)
        worker.polaris_catalogs[safe_alias] = {"endpoint": endpoint, "catalog": catalog, "alias": safe_alias,
                                               "client_id": client_id, "client_secret": client_secret}
        print(f"  Catalog '{safe_alias}' ({catalog}) attached for {worker.owner_email}")
        return {"status": "ok", "alias": safe_alias, "message": f"Connected: {safe_alias} ({catalog}). Query as: {safe_alias}.<namespace>.<table>"}
    except Exception as e:
        return {"status": "error", "message": str(e)}


def disconnect_polaris(alias):
    """Disconnect a Polaris catalog from the caller's worker."""
    safe_alias = alias.replace("-", "_").replace(" ", "_").lower()
    worker = _try_get_worker()
    if worker is None:
        return {"status": "ok", "message": f"No worker — nothing to disconnect for {safe_alias}"}
    try:
        worker.send_command("exec_multi", {"statements": [
            f"DETACH DATABASE IF EXISTS {safe_alias};",
            f"DROP SECRET IF EXISTS secret_{safe_alias};",
        ]}, timeout=15)
        worker.polaris_catalogs.pop(safe_alias, None)
        worker._s3_vended_cache.pop(safe_alias, None)
        return {"status": "ok", "message": f"Disconnected: {safe_alias}"}
    except Exception as e:
        return {"status": "error", "message": str(e)}


def _polaris_oauth_token(endpoint, client_id, client_secret):
    """Get an OAuth2 token from the Polaris REST API."""
    token_url = endpoint.rstrip("/") + "/v1/oauth/tokens"
    data = urllib.parse.urlencode({
        "grant_type": "client_credentials",
        "client_id": client_id,
        "client_secret": client_secret,
        "scope": "PRINCIPAL_ROLE:ALL",
    }).encode()
    req = __import__("urllib.request", fromlist=["Request"]).Request(token_url, data=data, method="POST",
                                 headers={"Content-Type": "application/x-www-form-urlencoded"})
    with __import__("urllib.request", fromlist=["urlopen"]).urlopen(req, timeout=15) as resp:
        return json.loads(resp.read())["access_token"]


def _polaris_rest_get(endpoint, path, token, extra_headers=None):
    """GET a Polaris REST API path with bearer token."""
    url = endpoint.rstrip("/") + path
    headers = {"Authorization": f"Bearer {token}"}
    if extra_headers:
        headers.update(extra_headers)
    req = __import__("urllib.request", fromlist=["Request"]).Request(url, headers=headers)
    with __import__("urllib.request", fromlist=["urlopen"]).urlopen(req, timeout=15) as resp:
        return json.loads(resp.read())


def _get_aws_polaris_token_and_creds(alias, worker: DuckDBWorker | None = None):
    """Get or refresh OAuth token + S3 vended credentials for an AWS Polaris
    catalog in the calling user's worker."""
    w = worker or _try_get_worker()
    if w is None:
        return None, None
    cache = w._s3_vended_cache.get(alias, {})
    if cache.get("expires", 0) > time.time() and cache.get("s3_creds"):
        return cache["token"], cache["s3_creds"]

    cat = w.polaris_catalogs.get(alias)
    if not cat:
        return None, None
    try:
        token = _polaris_oauth_token(cat["endpoint"], cat["client_id"], cat["client_secret"])
        catalog_name = cat["catalog"]
        # Get any table to fetch vended S3 credentials (they're catalog-wide)
        ns_data = _polaris_rest_get(cat["endpoint"], f"/v1/{catalog_name}/namespaces", token)
        namespaces = ns_data.get("namespaces", [])
        if not namespaces:
            return token, None
        ns_name = namespaces[0][0] if isinstance(namespaces[0], list) else namespaces[0]
        tbl_data = _polaris_rest_get(cat["endpoint"],
            f"/v1/{catalog_name}/namespaces/{ns_name}/tables", token)
        tables = tbl_data.get("identifiers", [])
        if not tables:
            return token, None
        tbl_name = tables[0].get("name", tables[0]) if isinstance(tables[0], dict) else tables[0]
        tbl_meta = _polaris_rest_get(cat["endpoint"],
            f"/v1/{catalog_name}/namespaces/{ns_name}/tables/{tbl_name}", token,
            extra_headers={"X-Iceberg-Access-Delegation": "vended-credentials"})
        s3_creds = tbl_meta.get("config", {})
        w._s3_vended_cache[alias] = {"token": token, "expires": time.time() + 3000, "s3_creds": s3_creds}
        # Create/refresh S3 secret in this user's DuckDB
        ak = s3_creds.get("s3.access-key-id", "")
        sk = s3_creds.get("s3.secret-access-key", "")
        st = s3_creds.get("s3.session-token", "")
        s3_region = s3_creds.get("s3.region") or _aws_region_from_endpoint(cat.get("endpoint", ""))
        if ak and sk:
            w.send_command("exec_multi", {"statements": [
                f"DROP SECRET IF EXISTS s3_vended_{alias};",
                f"""CREATE SECRET s3_vended_{alias} (
                    TYPE S3,
                    KEY_ID '{ak}',
                    SECRET '{sk}',
                    SESSION_TOKEN '{st}',
                    REGION '{s3_region}'
                );""",
            ]}, timeout=15)
            print(f"  S3 vended credentials refreshed for catalog '{alias}' region={s3_region} ({w.owner_email})")
        return token, s3_creds
    except Exception as e:
        print(f"  WARNING: Failed to get vended S3 credentials for {alias}: {e}")
        return None, None


def _rewrite_aws_query(query, worker: DuckDBWorker | None = None):
    """Rewrite queries targeting AWS Polaris catalogs to use iceberg_scan().

    DuckDB's ATTACH TYPE ICEBERG hangs on S3-backed catalogs because it doesn't
    send the X-Iceberg-Access-Delegation header needed for vended credentials.
    Workaround: resolve table metadata-location via REST API, then use iceberg_scan().
    """
    w = worker or _try_get_worker()
    if w is None:
        return query
    q_lower = query.lower().strip()

    # Find which AWS catalog alias is referenced (in this user's catalogs)
    target_alias = None
    for alias, cat in w.polaris_catalogs.items():
        if alias in q_lower and (".aws." in cat.get("endpoint", "") or "aws" in alias):
            target_alias = alias
            break
    if not target_alias:
        return query  # not an AWS query, return unchanged

    cat = w.polaris_catalogs[target_alias]
    catalog_name = cat["catalog"]

    # Extract table references like aws.namespace.table
    # Pattern: alias.namespace.table (possibly quoted)
    pattern = re.compile(
        rf'\b{re.escape(target_alias)}\.([a-zA-Z_][a-zA-Z0-9_]*)\.([a-zA-Z_][a-zA-Z0-9_]*)\b',
        re.IGNORECASE
    )
    matches = pattern.findall(query)
    if not matches:
        return query  # no table references found

    token, s3_creds = _get_aws_polaris_token_and_creds(target_alias, worker=w)
    if not token:
        return query  # can't get token, let it fail normally

    rewritten = query
    for namespace, table in matches:
        try:
            tbl_meta = _polaris_rest_get(cat["endpoint"],
                f"/v1/{catalog_name}/namespaces/{namespace}/tables/{table}", token,
                extra_headers={"X-Iceberg-Access-Delegation": "vended-credentials"})
            meta_loc = tbl_meta.get("metadata-location", "")
            if not meta_loc:
                continue
            full_ref = f"{target_alias}.{namespace}.{table}"
            replacement = f"iceberg_scan('{meta_loc}')"
            rewritten = re.sub(
                rf'\b{re.escape(target_alias)}\.{re.escape(namespace)}\.{re.escape(table)}\b',
                replacement, rewritten, flags=re.IGNORECASE
            )
            print(f"  AWS query rewrite ({w.owner_email}): {full_ref} -> iceberg_scan(...)")

            cfg = tbl_meta.get("config", {})
            ak = cfg.get("s3.access-key-id", "")
            sk = cfg.get("s3.secret-access-key", "")
            st = cfg.get("s3.session-token", "")
            s3_region = cfg.get("s3.region") or _aws_region_from_endpoint(cat.get("endpoint", ""))
            if ak and sk:
                w.send_command("exec_multi", {"statements": [
                    f"DROP SECRET IF EXISTS s3_vended_{target_alias};",
                    f"""CREATE SECRET s3_vended_{target_alias} (
                        TYPE S3,
                        KEY_ID '{ak}',
                        SECRET '{sk}',
                        SESSION_TOKEN '{st}',
                        REGION '{s3_region}'
                    );""",
                ]}, timeout=15)
        except Exception as e:
            print(f"  WARNING: Failed to resolve {target_alias}.{namespace}.{table}: {e}")

    return rewritten


def list_polaris_namespaces(alias):
    """List namespaces in the caller's attached catalog via Polaris REST API."""
    safe_alias = alias.replace("-", "_").replace(" ", "_").lower()
    worker = _try_get_worker()
    if worker is None or safe_alias not in worker.polaris_catalogs:
        return {"status": "error", "message": f"Catalog '{alias}' not connected"}
    cat = worker.polaris_catalogs[safe_alias]
    try:
        token = _polaris_oauth_token(cat["endpoint"], cat["client_id"], cat["client_secret"])
        result = _polaris_rest_get(cat["endpoint"], f"/v1/{cat['catalog']}/namespaces", token)
        namespaces = sorted([ns[0] if isinstance(ns, list) else ns for ns in result.get("namespaces", [])])
        return {"status": "ok", "namespaces": namespaces, "alias": safe_alias}
    except Exception as e:
        return {"status": "error", "message": str(e)}


def list_polaris_tables(alias, namespace):
    """List tables in a namespace via Polaris REST API (caller's catalogs)."""
    safe_alias = alias.replace("-", "_").replace(" ", "_").lower()
    worker = _try_get_worker()
    if worker is None or safe_alias not in worker.polaris_catalogs:
        return {"status": "error", "message": f"Catalog '{alias}' not connected"}
    cat = worker.polaris_catalogs[safe_alias]
    try:
        token = _polaris_oauth_token(cat["endpoint"], cat["client_id"], cat["client_secret"])
        ns_path = urllib.parse.quote(namespace, safe="")
        result = _polaris_rest_get(cat["endpoint"], f"/v1/{cat['catalog']}/namespaces/{ns_path}/tables", token)
        tables = sorted([t.get("name", t) if isinstance(t, dict) else t for t in result.get("identifiers", [])])
        return {"status": "ok", "namespace": namespace, "tables": tables, "alias": safe_alias}
    except Exception as e:
        return {"status": "error", "message": str(e)}


def list_all_polaris_tables():
    """List all tables across all of the caller's connected catalogs."""
    worker = _try_get_worker()
    if worker is None or not worker.polaris_catalogs:
        return {"status": "ok", "tables": []}
    tables = []
    for alias, cat in list(worker.polaris_catalogs.items()):
        try:
            token = _polaris_oauth_token(cat["endpoint"], cat["client_id"], cat["client_secret"])
            ns_result = _polaris_rest_get(cat["endpoint"], f"/v1/{cat['catalog']}/namespaces", token)
            for ns in ns_result.get("namespaces", []):
                ns_name = ns[0] if isinstance(ns, list) else ns
                ns_path = urllib.parse.quote(ns_name, safe="")
                tbl_result = _polaris_rest_get(cat["endpoint"], f"/v1/{cat['catalog']}/namespaces/{ns_path}/tables", token)
                for t in tbl_result.get("identifiers", []):
                    tbl_name = t.get("name", t) if isinstance(t, dict) else t
                    tables.append({"namespace": ns_name, "name": tbl_name, "fqn": f"{alias}.{ns_name}.{tbl_name}", "alias": alias})
        except Exception:
            pass
    return {"status": "ok", "tables": tables}


def get_connected_catalogs():
    """Return the caller's connected catalogs."""
    worker = _try_get_worker()
    if worker is None:
        return {"status": "ok", "catalogs": []}
    return {"status": "ok", "catalogs": [
        {"alias": a, "endpoint": v["endpoint"], "catalog": v["catalog"]}
        for a, v in worker.polaris_catalogs.items()
    ]}


def _resolve_polaris_creds(provider: str) -> dict:
    """Return the caller's resolved Polaris config for a provider:
    user_polaris_creds overlay if any, else CATALOG_PRESETS baseline.

    Always merges in the static label + default_alias from CATALOG_PRESETS so
    the UI can render a friendly title regardless of overlay presence."""
    base = CATALOG_PRESETS.get(provider, {})
    out = {
        "label":         base.get("label", provider),
        "default_alias": base.get("default_alias", provider),
        "endpoint":      base.get("endpoint", ""),
        "catalog":       base.get("catalog", ""),
        "client_id":     base.get("client_id", ""),
        "client_secret": base.get("client_secret", ""),
        "source":        "shared",
    }
    email = _current_request_email()
    if not email:
        return out
    try:
        import db_manager as _db
        row = _db.user_polaris_get(email, provider)
    except Exception as e:
        print(f"  _resolve_polaris_creds: DB read failed for {email}/{provider}: {e}")
        return out
    if not row:
        return out
    return {
        "label":         out["label"],
        "default_alias": out["default_alias"],
        "endpoint":      row.get("endpoint") or out["endpoint"],
        "catalog":       row.get("catalog") or out["catalog"],
        "client_id":     row.get("client_id") or out["client_id"],
        "client_secret": row.get("client_secret") or out["client_secret"],
        "source":        "user",
    }


def get_catalog_presets():
    """Return the caller's resolved presets per provider (overlay → baseline).
    Secrets are masked for display."""
    safe = {}
    for prov in CATALOG_PRESETS:
        merged = _resolve_polaris_creds(prov)
        out = dict(merged)  # copy
        s = out.get("client_secret") or ""
        out["client_secret_masked"] = s[:4] + "..." + s[-4:] if len(s) > 8 else "***"
        safe[prov] = out
    return {"status": "ok", "presets": safe}


def update_polaris_credentials(data):
    """Persist the caller's Polaris credential overlay for a provider.
    Never mutates CATALOG_PRESETS — that's the org-wide baseline."""
    provider = (data.get("provider") or "").lower()
    if provider not in CATALOG_PRESETS:
        return {"status": "error", "message": f"Unknown provider: {provider}. Use gcs, azure, or aws."}
    email = _current_request_email()
    if not email:
        return {"status": "error", "message": "Sign in required."}
    endpoint = (data.get("endpoint") or "").strip()
    catalog = (data.get("catalog") or "").strip()
    client_id = (data.get("client_id") or "").strip()
    client_secret = (data.get("client_secret") or "").strip()
    if not endpoint or not catalog or not client_id or not client_secret:
        return {"status": "error", "message": "All fields are required: endpoint, catalog, client_id, client_secret"}
    try:
        import db_manager as _db
        _db.user_polaris_upsert(email, provider, endpoint, catalog, client_id, client_secret, updated_by=email)
    except Exception as e:
        return {"status": "error", "message": f"Could not persist: {e}"}
    # Drop the caller's existing attach for this provider so the next Connect
    # picks up the new creds. Other users are untouched (their workers are separate).
    alias = CATALOG_PRESETS[provider].get("default_alias", provider)
    safe_alias = alias.replace("-", "_").replace(" ", "_").lower()
    worker = _try_get_worker()
    if worker is not None and safe_alias in worker.polaris_catalogs:
        try:
            disconnect_polaris(safe_alias)
        except Exception:
            pass
    return {"status": "ok", "message": f"Credentials saved for {CATALOG_PRESETS[provider].get('label', provider)} (your account only). Click the button above to reconnect."}


def reset_polaris_credentials(data):
    """Drop the caller's overlay row for a provider — the user falls back
    to the shared CATALOG_PRESETS baseline on next read."""
    provider = (data.get("provider") or "").lower()
    if provider not in CATALOG_PRESETS:
        return {"status": "error", "message": f"Unknown provider: {provider}"}
    email = _current_request_email()
    if not email:
        return {"status": "error", "message": "Sign in required."}
    try:
        import db_manager as _db
        removed = _db.user_polaris_delete(email, provider)
    except Exception as e:
        return {"status": "error", "message": f"Could not reset: {e}"}
    # Disconnect this provider's attach in the caller's worker so next Connect
    # picks up the now-restored shared baseline.
    alias = CATALOG_PRESETS[provider].get("default_alias", provider)
    safe_alias = alias.replace("-", "_").replace(" ", "_").lower()
    worker = _try_get_worker()
    if worker is not None and safe_alias in worker.polaris_catalogs:
        try:
            disconnect_polaris(safe_alias)
        except Exception:
            pass
    return {"status": "ok",
            "message": ("Reverted to shared baseline." if removed
                        else "No personal overlay was set — shared baseline already in use.")}


# ── Listing cache + lazy-stats guard ─────────────────────────────────────────
# Big dataset dirs (totalfix/SUMDMO_*, tens of thousands of table folders) are
# slow to browse for two reasons: (1) per-folder file-count/size stats need a
# DEEP, non-delimited scan of every parquet blob under the parent — O(all blobs)
# — and (2) re-opening the same folder repeats that scan. We cache the assembled
# listing per (bucket, prefix) with a short TTL, and skip the deep stat scan once
# a directory has more than _DIR_STATS_MAX_PREFIXES subfolders (folders still
# open instantly; only the file-count/size columns are omitted for huge dirs).
_LIST_CACHE = {}
_LIST_CACHE_TTL = 300      # seconds a cached listing stays fresh
_LIST_CACHE_MAX = 256      # cap distinct (bucket, prefix) entries kept in memory
_DIR_STATS_MAX_PREFIXES = 300  # above this many immediate subdirs, skip stats
_DIR_STATS_SCAN_CAP = 10000    # abort the deep stat scan past this many blobs


def _get_dir_stats(bucket, prefixes, parent_prefix, scan_cap=_DIR_STATS_SCAN_CAP):
    """Aggregate parquet file count/size per immediate subdirectory.

    This is a DEEP (non-delimited) listing, so its cost scales with the TOTAL
    number of objects under parent_prefix — not the number of immediate
    subfolders. A dir with only a couple of subfolders can still sit atop a
    million+ objects (e.g. totalfix/SUMDMO_oracle/). We therefore bound the
    scan: if more than `scan_cap` blobs are seen we abort and report
    truncated=True, and the caller omits stats rather than block for ~25s.

    Returns (stats_dict, truncated)."""
    stats = {}
    if not prefixes:
        return stats, False
    # Do a bounded deep listing of parent prefix and aggregate by directory
    try:
        gcs = _gcs()
    except NeedsGoogleAuth:
        return stats, False
    scanned = 0
    try:
        all_blobs = gcs.list_blobs(bucket, prefix=parent_prefix)
        for blob in all_blobs:
            scanned += 1
            if scanned > scan_cap:
                return {}, True  # too big to stat cheaply — bail, let caller skip
            if not blob.name.endswith(".parquet") or "_delta_log" in blob.name:
                continue
            # Find which directory this blob belongs to
            rel = blob.name[len(parent_prefix):]
            parts = rel.split("/")
            if len(parts) >= 2:
                dir_name = parts[0]
                key = parent_prefix + dir_name + "/"
                if key in prefixes:
                    if key not in stats:
                        stats[key] = {"files": 0, "total_size": 0}
                    stats[key]["files"] += 1
                    stats[key]["total_size"] += (blob.size or 0)
    except Exception:
        pass
    return stats, False


def list_path(prefix, bucket_name=None):
    """List directories and files under a GCS prefix."""
    global current_bucket
    if bucket_name:
        current_bucket = bucket_name
    try:
        gcs = _gcs()
    except NeedsGoogleAuth:
        return _google_auth_response()

    # Serve a fresh cached listing without touching GCS (fast re-browse).
    ck = (current_bucket, prefix)
    now = _time_mod.time()
    hit = _LIST_CACHE.get(ck)
    if hit and (now - hit[0]) < _LIST_CACHE_TTL:
        _save_state(current_bucket, prefix)
        return hit[1]

    try:
        bucket = gcs.bucket(current_bucket)
        iterator = gcs.list_blobs(bucket, prefix=prefix, delimiter="/")
        blobs = list(iterator)
        prefixes = sorted(iterator.prefixes)

        # Gather stats only inside dataset directories under sap_cds_views/,
        # and only when the folder count is small enough to stat cheaply.
        # Huge dirs (SUMDMO_* with 50k+ table folders) skip the deep scan so
        # they open instantly — file-count/size columns are simply omitted.
        prefix_set = set(prefixes)
        is_dataset_dir = (current_bucket == BUCKET_NAME
                          and prefix.startswith(BASE_PREFIX)
                          and prefix.count("/") >= 2)
        stats_skipped = is_dataset_dir and len(prefixes) > _DIR_STATS_MAX_PREFIXES
        dir_stats = {}
        if is_dataset_dir and not stats_skipped:
            dir_stats, truncated = _get_dir_stats(bucket, prefix_set, prefix)
            if truncated:
                # Subtree too large to stat within the blob cap — skip stats,
                # still return the folders instantly.
                dir_stats, stats_skipped = {}, True

        items = []
        for p in prefixes:
            name = p.rstrip("/").split("/")[-1]
            st = dir_stats.get(p, {})
            items.append({
                "name": name + "/",
                "path": p,
                "is_dir": True,
                "size": st.get("total_size", ""),
                "file_count": st.get("files", 0)
            })
        for blob in blobs:
            if blob.name == prefix:
                continue
            name = blob.name.split("/")[-1]
            if not name:
                continue
            items.append({
                "name": name,
                "path": blob.name,
                "is_dir": False,
                "size": blob.size,
                "file_count": 0,
                "updated": (blob.updated.isoformat() if blob.updated else None),
            })

        # Persist navigation state
        _save_state(current_bucket, prefix)

        result = {"status": "ok", "items": items, "prefix": prefix,
                  "bucket": current_bucket, "stats_skipped": stats_skipped,
                  "total_items": len(items)}
        # Cache the assembled listing (bounded; simple clear on overflow).
        if len(_LIST_CACHE) >= _LIST_CACHE_MAX:
            _LIST_CACHE.clear()
        _LIST_CACHE[ck] = (now, result)
        return result
    except Exception as e:
        return {"status": "error", "message": str(e)}


def read_parquet(blob_path):
    """Read a parquet file from GCS into memory and return as table data."""
    try:
        worker = _get_worker()
    except RuntimeError as e:
        return {"status": "error", "message": str(e)}
    _maybe_evict(worker)
    try:
        gcs = _gcs()
    except NeedsGoogleAuth:
        return _google_auth_response()
    try:
        bucket = gcs.bucket(current_bucket)
        blob = bucket.blob(blob_path)
        data = blob.download_as_bytes()
        table = pq.read_table(io.BytesIO(data))

        table_name = blob_path.split("/")[-1].replace(".parquet", "").replace("-", "_")
        if table_name[0:1].isdigit():
            table_name = "t_" + table_name
        parts = blob_path.split("/")
        dir_name = table_name
        if len(parts) >= 3:
            dir_name = parts[-3] if parts[-2] == "data" else parts[-2]
            dir_name = dir_name.replace("-", "_")
            if dir_name[0:1].isdigit():
                dir_name = "t_" + dir_name

        ipc_bytes = _serialize_arrow_table(table)
        if dir_name != table_name:
            worker.send_command("register_table", {"name": dir_name, "ipc_bytes": ipc_bytes}, timeout=30)
            worker.loaded_tables[dir_name] = {"rows": table.num_rows, "columns": list(table.column_names), "nbytes": table.nbytes}
        worker.send_command("register_table", {"name": table_name, "ipc_bytes": ipc_bytes}, timeout=30)
        worker.loaded_tables[table_name] = {"rows": table.num_rows, "columns": list(table.column_names), "nbytes": table.nbytes}

        columns = [field.name for field in table.schema]
        num_rows = table.num_rows
        limit = min(num_rows, 2000)
        rows = []
        for i in range(limit):
            rows.append([
                str(table.column(c)[i].as_py()) if table.column(c)[i].as_py() is not None else ""
                for c in range(len(columns))
            ])

        return {
            "status": "ok",
            "columns": columns,
            "rows": rows,
            "total_rows": num_rows,
            "displayed_rows": limit,
            "schema": str(table.schema),
            "registered_as": dir_name
        }
    except Exception as e:
        return {"status": "error", "message": str(e)}


def read_all_parquets_in_dir(dir_path):
    """Read all parquet files in a data/ directory and combine them."""
    try:
        worker = _get_worker()
    except RuntimeError as e:
        return {"status": "error", "message": str(e)}
    _maybe_evict(worker)
    try:
        gcs = _gcs()
    except NeedsGoogleAuth:
        return _google_auth_response()
    try:
        bucket = gcs.bucket(current_bucket)
        data_prefix = dir_path if dir_path.endswith("data/") else dir_path + "data/"
        blobs = list(gcs.list_blobs(bucket, prefix=data_prefix))
        parquet_blobs = [b for b in blobs if b.name.endswith(".parquet")]

        if not parquet_blobs:
            return {"status": "error", "message": "No parquet files found in " + data_prefix}

        tables = []
        for blob in parquet_blobs:
            data = blob.download_as_bytes()
            tables.append(pq.read_table(io.BytesIO(data)))

        combined = pyarrow.concat_tables(tables)

        parts = dir_path.rstrip("/").split("/")
        dir_name = parts[-1] if parts[-1] != "data" else parts[-2]
        dir_name = dir_name.replace("-", "_")
        if dir_name[0:1].isdigit():
            dir_name = "t_" + dir_name

        ipc_bytes = _serialize_arrow_table(combined)
        worker.send_command("register_table", {"name": dir_name, "ipc_bytes": ipc_bytes}, timeout=30)
        worker.loaded_tables[dir_name] = {"rows": combined.num_rows, "columns": list(combined.column_names), "nbytes": combined.nbytes}

        columns = [field.name for field in combined.schema]
        num_rows = combined.num_rows
        limit = min(num_rows, 2000)
        rows = []
        for i in range(limit):
            rows.append([
                str(combined.column(c)[i].as_py()) if combined.column(c)[i].as_py() is not None else ""
                for c in range(len(columns))
            ])

        return {
            "status": "ok",
            "columns": columns,
            "rows": rows,
            "total_rows": num_rows,
            "displayed_rows": limit,
            "schema": str(combined.schema),
            "registered_as": dir_name,
            "files_read": len(parquet_blobs)
        }
    except Exception as e:
        return {"status": "error", "message": str(e)}


def auto_load_table(table_name, browse_prefix=""):
    """Auto-load a table from GCS into the caller's worker."""
    try:
        worker = _get_worker()
    except RuntimeError:
        return False
    _maybe_evict(worker)
    try:
        gcs = _gcs()
    except NeedsGoogleAuth:
        return False
    try:
        bucket = gcs.bucket(current_bucket)
        search_name = table_name.lower()

        candidates = []
        if browse_prefix:
            parts = browse_prefix.rstrip("/").split("/")
            if len(parts) >= 2:
                dataset = "/".join(parts[:2]) + "/"
                candidates.append(dataset + search_name + "/data/")
                candidates.append(dataset + search_name + "/")

        for candidate in candidates:
            blobs = list(gcs.list_blobs(bucket, prefix=candidate, max_results=20))
            parquet_blobs = [b for b in blobs if b.name.endswith(".parquet") and "_delta_log" not in b.name]
            if parquet_blobs:
                tables = []
                for blob in parquet_blobs:
                    data = blob.download_as_bytes()
                    tables.append(pq.read_table(io.BytesIO(data)))
                combined = pyarrow.concat_tables(tables) if len(tables) > 1 else tables[0]
                ipc_bytes = _serialize_arrow_table(combined)
                worker.send_command("register_table", {"name": search_name, "ipc_bytes": ipc_bytes}, timeout=30)
                worker.loaded_tables[search_name] = {"rows": combined.num_rows, "columns": list(combined.column_names), "nbytes": combined.nbytes}
                print(f"  Auto-loaded: {search_name} ({combined.num_rows} rows) for {worker.owner_email}")
                return True
        return False
    except Exception as e:
        print(f"  Auto-load failed for {table_name}: {e}")
        return False


import re as _re

def _extract_missing_table(error_msg):
    """Extract the missing table name from a DuckDB error message."""
    m = _re.search(r'Table with name (\S+) does not exist', error_msg)
    return m.group(1).strip('"').lower() if m else None


def _ensure_polaris_attached(query, worker):
    """Self-heal Polaris catalog attaches in a freshly-(re)spawned worker.

    A worker's DuckDB connection loses every ATTACH + storage secret when it is
    reaped (idle >30 min), LRU-evicted, or respawned after a hung query — yet the
    browser still shows the catalog as "Connected" (frontend state is client-side
    and never refreshed). Without this, the next query fails with
    'Binder Error: Catalog "..." does not exist!'.

    For any known catalog alias referenced by this query but not currently
    attached in the caller's worker, transparently re-attach it (and re-establish
    the per-worker storage secret) using the caller's resolved credentials —
    exactly what the frontend's connectCloud() does, but server-side.

      - azure: re-ATTACH + recreate azure_storage_secret (CREDENTIAL_CHAIN) — both
               are per-worker DuckDB state lost on respawn.
      - gcs:   re-ATTACH only — GCS storage auth is filesystem ADC, survives respawn.
      - aws:   re-ATTACH only — vended S3 creds are re-fetched at query time by
               _rewrite_aws_query() (its _s3_vended_cache was cleared on respawn).
    """
    if worker is None:
        return
    q_lower = query.lower()
    for provider, base in CATALOG_PRESETS.items():
        alias = base.get("default_alias") or provider
        safe_alias = alias.replace("-", "_").replace(" ", "_").lower()
        if safe_alias in worker.polaris_catalogs:
            continue  # already attached in this worker
        if (safe_alias + ".") not in q_lower:
            continue  # not referenced by this query
        creds = _resolve_polaris_creds(provider)
        if not creds.get("client_id") or not creds.get("client_secret"):
            continue  # no usable creds — let the query fail with its normal error
        print(f"  Self-heal: re-attaching '{safe_alias}' ({provider}) for "
              f"{worker.owner_email} — worker was reaped/respawned")
        r = connect_polaris(safe_alias, creds["endpoint"], creds["catalog"],
                            creds["client_id"], creds["client_secret"])
        if r.get("status") != "ok":
            print(f"  Self-heal: re-attach failed for '{safe_alias}': {r.get('message')}")
            continue
        if provider == "azure":
            try:
                run_azure_auth()
            except Exception as _e:
                print(f"  Self-heal: azure storage secret failed: {_e}")


def run_sql(query, browse_prefix=""):
    """Execute a SQL query via the caller's DuckDB worker. Auto-loads tables
    from GCS if not found."""
    try:
        worker = _get_worker()
    except RuntimeError as e:
        return {"status": "error", "message": str(e)}
    try:
        import datetime as _dtm
        with open("/var/log/portal/duckdb_trace.log", "a") as _df:
            _df.write(_dtm.datetime.now().strftime("%Y-%m-%d %H:%M:%S") + " " +
                      worker.owner_email + " QUERY: " +
                      query[:300].replace("\n", " ") + "\n")
    except Exception:
        pass
    def _exec(q, timeout_sec=45):
        result = worker.send_command("exec_sql", {"query": q}, timeout=timeout_sec + 5)
        return result["cols"], result["data"]

    # Self-heal: re-attach any referenced Polaris catalog this worker lost to an
    # idle reap / LRU evict / hung-query respawn, so queries don't fail with
    # 'Catalog "..." does not exist' while the frontend still shows "Connected".
    try:
        _ensure_polaris_attached(query, worker)
    except Exception as _e:
        print(f"  _ensure_polaris_attached error: {_e}")

    # Rewrite AWS Polaris queries to use iceberg_scan() with vended S3 credentials
    query = _rewrite_aws_query(query, worker=worker)

    try:
        columns, rows = _exec(query)
    except Exception as e:
        error_msg = str(e)
        missing = _extract_missing_table(error_msg)
        if missing and missing not in worker.loaded_tables:
            if auto_load_table(missing, browse_prefix):
                try:
                    columns, rows = _exec(query)
                except Exception as e2:
                    missing2 = _extract_missing_table(str(e2))
                    if missing2 and missing2 not in worker.loaded_tables and auto_load_table(missing2, browse_prefix):
                        try:
                            columns, rows = _exec(query)
                        except Exception as e3:
                            return {"status": "error", "message": str(e3)}
                    else:
                        return {"status": "error", "message": str(e2)}
            else:
                return {"status": "error", "message": error_msg}
        else:
            return {"status": "error", "message": error_msg}

    try:

        safe_rows = []
        for row in rows:
            safe_row = []
            for v in row:
                if v is None:
                    safe_row.append("")
                elif isinstance(v, str):
                    safe_row.append(v)
                else:
                    safe_row.append(str(v))
            safe_rows.append(safe_row)

        return {
            "status": "ok",
            "columns": columns,
            "rows": safe_rows,
            "total_rows": len(rows)
        }
    except Exception as e:
        return {"status": "error", "message": str(e)}


def read_file_text(blob_path):
    """Read a text file from GCS."""
    try:
        gcs = _gcs()
    except NeedsGoogleAuth:
        return _google_auth_response()
    try:
        bucket = gcs.bucket(current_bucket)
        blob = bucket.blob(blob_path)
        content = blob.download_as_text()
        return {"status": "ok", "content": content[:100000]}
    except Exception as e:
        return {"status": "error", "message": str(e)}




def get_loaded_tables():
    """Return the caller's registered DuckDB tables."""
    worker = _try_get_worker()
    if worker is None:
        return {"status": "ok", "tables": []}
    tables = []
    for name, meta in worker.loaded_tables.items():
        if isinstance(meta, dict):
            tables.append({
                "name": name,
                "rows": meta.get("rows", 0),
                "columns": len(meta.get("columns", [])),
                "column_names": meta.get("columns", [])
            })
        else:
            tables.append({
                "name": name,
                "rows": meta.num_rows,
                "columns": len(meta.column_names),
                "column_names": list(meta.column_names)
            })
    return {"status": "ok", "tables": tables}


