        # --- ECC OTC Quick Run kickoff/abort (any logged-in user) — proxy to sapotc-aba-daemon ---
        if (self.path == "/sap_skills/api/ecc_otc_quick_run"
                or self.path.startswith("/sap_skills/api/ecc_otc_quick_run/")):
            _sess = self._require_session(min_role="user")
