                    "FTS: fts_main_attach_index.match_bm25(message_id,\'query\')\n\n"
                    "=== TABLE: calendar_index (1,426 calendar invites parsed from email subjects) ===\n"
                    "  message_id          VARCHAR   FK -> email_index.id\n"
                    "  event_summary       VARCHAR   Event title (subject prefix stripped)\n"
                    "  event_start         VARCHAR   \'YYYY-MM-DD HH:MM:SS\' or NULL\n"
