                    "  action              VARCHAR   INVITATION|UPDATED|ACCEPTED|CANCELLED|TENTATIVE|DECLINED\n"
                    "  sender              VARCHAR   Email sender\n"
                    "  snippet             VARCHAR   Email snippet/description\n"
                    "FTS: fts_main_calendar_index.match_bm25(message_id,\'query\')\n\n"
                    "=== LABELS ===\n"
                    "INBOX=received  SENT=sent-by-Antonio  CATEGORY_*=auto-categorized  IMPORTANT=flagged  STARRED=starred\n\n"
                    "=== KEY QUERY PATTERNS ===\n"
                    "# Contact lookup:\n"
                    "SELECT DISTINCT sender FROM email_index WHERE lower(sender) LIKE \'%company%\' OR lower(recipient) LIKE \'%company%\' LIMIT 20\n\n"
                    "# Received (inbox): WHERE labels LIKE \'%INBOX%\'\n"
                    "# Sent (outbox):    WHERE labels LIKE \'%SENT%\'\n\n"
                    "# Calendar: time spent with a company:\n"
                    "SELECT COUNT(*) meetings, SUM(event_duration_mins) total_mins, ROUND(SUM(event_duration_mins)/60.0,1) hours\n"
                    "FROM calendar_index WHERE (lower(attendees) LIKE \'%company%\' OR lower(event_summary) LIKE \'%company%\') AND action NOT IN (\'CANCELLED\',\'DECLINED\')\n\n"
                    "# Calendar: list events with a company:\n"
                    "SELECT event_summary,event_start,event_duration_mins,organizer,attendees FROM calendar_index WHERE lower(event_summary) LIKE \'%company%\' OR lower(attendees) LIKE \'%company%\' ORDER BY event_start DESC NULLS LAST\n\n"
                    "# Date filter: internal_date is MILLISECONDS — last 30 days:\n"
                    "WHERE internal_date > (EXTRACT(EPOCH FROM NOW())-30*86400)*1000\n\n"
                    "# FTS search: fts_main_email_index.match_bm25(id,\'term\') IS NOT NULL ORDER BY score DESC\n\n"
                    "=== RULES ===\n"
