        # --- Snowflake Query API ---
        if parsed.path == "/sap_skills/api/snowflake_query":
            try:
                import base64, vault_manager, importlib
                importlib.reload(vault_manager)
                from cryptography.hazmat.backends import default_backend
                from cryptography.hazmat.primitives.serialization import (
                    load_pem_private_key, Encoding, PrivateFormat, NoEncryption)
                import snowflake.connector
                length = int(self.headers.get("Content-Length", 0))
                body = json.loads(self.rfile.read(length)) if length else {}
                sql = body.get("sql", "").strip()
                database = body.get("database", "ANTONIO_CARBONE").strip() or "ANTONIO_CARBONE"
                schema = body.get("schema", "").strip()
                if not sql:
                    self.send_json({"status": "error", "message": "No SQL provided"})
                    return
                mk = open("/usr/sap/sap_skills/.master_key").read().strip()
                creds = vault_manager.get_entry(mk, "snowflake_sales_eng")
                if not creds:
                    self.send_json({"status": "error", "message": "snowflake_sales_eng not found in vault"})
                    return
                key_data = base64.b64decode(creds["key_b64"])
                key = load_pem_private_key(key_data, password=creds["key_passphrase"].encode(), backend=default_backend())
                pk_bytes = key.private_bytes(Encoding.DER, PrivateFormat.PKCS8, NoEncryption())
                params = dict(account=creds["account"], user=creds["user"],
                              private_key=pk_bytes, warehouse=creds["warehouse"],
                              database=database)
                if schema: params["schema"] = schema
                params.update(login_timeout=10, network_timeout=15)
                conn = snowflake.connector.connect(**params)
                cur = conn.cursor()
                cur.execute(sql)
                columns = [desc[0] for desc in cur.description] if cur.description else []
                rows = []
                for row in cur.fetchall():
                    rows.append([str(c) if c is not None else None for c in row])
                conn.close()
                self.send_json({"status": "ok", "columns": columns, "rows": rows,
                    "row_count": len(rows), "truncated": False})
            except Exception as e:
                self.send_json({"status": "error", "message": str(e)})
            return

