        # --- Audit log viewer (admin-only — gate already enforced) ---
        # Phase 1b (2026-04-25): reads from Postgres `activity_events` table,
        # falls back to CSV if the DB is unreachable. Same response shape as
        # before so SAP_User_Admin.html UI is unchanged.
        if parsed.path == "/sap_skills/api/audit/list":
            try:
                from urllib.parse import parse_qs as _pqs
                _q = _pqs(parsed.query)
                _limit = int((_q.get("limit") or ["500"])[0])
                _limit = max(1, min(_limit, 5000))
                _filter_action = (_q.get("action") or [""])[0].strip().lower()
                _filter_actor  = (_q.get("actor")  or [""])[0].strip().lower()
                _filter_target = (_q.get("target") or [""])[0].strip().lower()
                _filter_q      = (_q.get("q")      or [""])[0].strip().lower()

                rows = []
                actions = []
                _source = "db"
                _err = None

                # ---- Path A: Postgres ----
                try:
                    import sys as _sys
                    if "/usr/sap/sap_skills" not in _sys.path:
                        _sys.path.insert(0, "/usr/sap/sap_skills")
                    import db_manager as _dbm

                    # Build SQL with ANDed filters. Always restrict to user_action.
                    _conds = ["type = %s"]
                    _params = ["user_action"]
                    if _filter_action:
                        _conds.append("lower(action) = %s")
                        _params.append(_filter_action)
                    if _filter_actor:
                        _conds.append("lower(coalesce(actor_email,'')) LIKE %s")
                        _params.append(f"%{_filter_actor}%")
                    if _filter_target:
                        _conds.append("(lower(coalesce(target_email,'')) LIKE %s OR lower(coalesce(actor_email,'')) LIKE %s)")
                        _params.append(f"%{_filter_target}%")
                        _params.append(f"%{_filter_target}%")
                    if _filter_q:
                        _conds.append("(lower(action) LIKE %s OR lower(coalesce(detail,'')) LIKE %s OR lower(coalesce(actor_email,'')) LIKE %s)")
                        _params.append(f"%{_filter_q}%")
                        _params.append(f"%{_filter_q}%")
                        _params.append(f"%{_filter_q}%")
                    _sql = f"""
                        SELECT to_char(ts_utc AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US') AS ts_iso,
                               action, actor_email, target_email, ip::text AS ip_text,
                               result, detail,
                               geo_city, geo_country_code, geo_region, geo_country, geo_isp
                          FROM activity_events
                         WHERE {' AND '.join(_conds)}
                         ORDER BY ts_utc DESC
                         LIMIT %s
                    """
                    _params.append(_limit)
                    _result = _dbm.read(_sql, tuple(_params))

                    # Reconstitute the CSV-style "actor=...; target=...; ip=...; <info>"
                    # detail string so the UI rendering doesn't change.
                    for r in _result:
                        _parts = []
                        if r.get("actor_email"):     _parts.append(f"actor={r['actor_email']}")
                        if r.get("target_email") and r["target_email"] != r.get("actor_email"):
                            _parts.append(f"target={r['target_email']}")
                        if r.get("ip_text"):         _parts.append(f"ip={r['ip_text']}")
                        if r.get("detail"):          _parts.append(r["detail"])
                        _geo_parts = [p for p in [r.get("geo_city"), r.get("geo_region"),
                                                               r.get("geo_country")] if p]
                        _geo_full_str = ", ".join(_geo_parts)
                        if r.get("geo_isp"): _geo_full_str += " — " + r["geo_isp"]
                        rows.append({
                            "timestamp": (r["ts_iso"] or "") + "+00:00",
                            "date":      (r["ts_iso"] or "")[:10],
                            "time":      (r["ts_iso"] or "")[11:19],
                            "action":    r.get("action") or "",
                            "result":    r.get("result") or "",
                            "detail":    "; ".join(_parts),
                            "ip":        (r.get("ip_text") or "").split("/")[0],
                            "geo":       _geo_full_str,
                        })

                    # Distinct action list (unfiltered) for the dropdown
                    _action_rows = _dbm.read(
                        "SELECT DISTINCT action FROM activity_events WHERE type='user_action' ORDER BY action"
                    )
                    actions = [r["action"] for r in _action_rows if r.get("action")]
                except Exception as _e:
                    _err = str(_e)
                    _source = "csv-fallback"

                # ---- Path B: CSV fallback (only if DB read failed) ----
                if _source == "csv-fallback":
                    import csv as _csv
                    _csv_path = "/var/log/portal/sap_portal_activity.csv"
                    _action_set = set()
                    rows = []
                    if os.path.exists(_csv_path):
                        with open(_csv_path, "r", newline="") as _f:
                            for row in _csv.DictReader(_f):
                                if row.get("type") != "user_action":
                                    continue
                                _action_set.add(row.get("action",""))
                                if _filter_action and row.get("action","").lower() != _filter_action:
                                    continue
                                _det = (row.get("detail","") or "").lower()
                                if _filter_actor and f"actor={_filter_actor}" not in _det:
                                    continue
                                if _filter_target:
                                    if (f"target={_filter_target}" not in _det
                                            and f"actor={_filter_target}" not in _det):
                                        continue
                                if _filter_q and _filter_q not in (row.get("action","") + " " + _det).lower():
                                    continue
                                rows.append({
                                    "timestamp": row.get("timestamp_utc",""),
                                    "date":      row.get("date",""),
                                    "time":      row.get("time",""),
                                    "action":    row.get("action",""),
                                    "result":    row.get("result",""),
                                    "detail":    row.get("detail",""),
                                })
                    rows.reverse()
                    rows = rows[:_limit]
                    actions = sorted(_action_set)

                resp = json.dumps({
                    "status": "ok",
                    "count":   len(rows),
                    "actions": actions,
                    "rows":    rows,
                    "source":  _source,
                    "db_error": _err,
                }).encode()
            except Exception as _e:
                resp = json.dumps({"status":"error","message":str(_e)}).encode()
            self.send_response(200); self.send_header("Content-Type","application/json")
            self.send_header("Content-Length", str(len(resp)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers(); self.wfile.write(resp); return

        # --- /sap_skills/api/audit/lang_usage --- admin-only language &
        # activity analytics. Aggregates page_view events from activity_events
        # over the last N days into 4 views: by-language, by-user-language,
        # top-pages, by-user. Path classifier already sends /audit/* to admin.
        if parsed.path == "/sap_skills/api/audit/lang_usage":
            try:
                from urllib.parse import parse_qs as _pqs
                _q = _pqs(parsed.query)
                _days = max(1, min(365, int((_q.get("days") or ["30"])[0])))

                import sys as _sys
                if "/usr/sap/sap_skills" not in _sys.path:
                    _sys.path.insert(0, "/usr/sap/sap_skills")
                import db_manager as _dbm

                # NOTE: the LIKE patterns below use %% (doubled) on purpose.
                # _by_lang/_by_user_lang/_top_pages/_by_user are passed to
                # _dbm.read(sql, (_days,)) where psycopg parses %s/%b/%t — any
                # literal % in the SQL must be escaped as %%, otherwise psycopg
                # errors with "only '%s', '%b', '%t' are allowed as placeholders".
                # DO NOT collapse %%_ES.html → %_ES.html or /sap_skills/%% → /%.
                _lang_case = """CASE
                    WHEN detail = '/sap_skills/index.html'    THEN 'EN'
                    WHEN detail = '/sap_skills/index_ES.html' THEN 'ES'
                    WHEN detail = '/sap_skills/index_PT.html' THEN 'PT'
                    WHEN detail = '/sap_skills/index_IT.html' THEN 'IT'
                    WHEN detail = '/sap_skills/index_NL.html' THEN 'NL'
                    WHEN detail = '/sap_skills/index_DE.html' THEN 'DE'
                    WHEN detail LIKE '%%_ES.html' THEN 'ES'
                    WHEN detail LIKE '%%_PT.html' THEN 'PT'
                    WHEN detail LIKE '%%_IT.html' THEN 'IT'
                    WHEN detail LIKE '%%_NL.html' THEN 'NL'
                    WHEN detail LIKE '%%_DE.html' THEN 'DE'
                    ELSE 'EN'
                END"""
                _where = ("type='user_action' AND action='page_view' "
                          "AND detail LIKE '/sap_skills/%%' "
                          "AND ts_utc > now() - make_interval(days => %s)")

                _by_lang = _dbm.read(
                    f"""SELECT {_lang_case} AS lang,
                               count(*)::int AS page_views,
                               count(DISTINCT actor_email)::int AS unique_users,
                               to_char(max(ts_utc) AT TIME ZONE 'UTC',
                                       'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS last_seen
                          FROM activity_events
                         WHERE {_where}
                      GROUP BY 1
                      ORDER BY page_views DESC""",
                    (_days,)
                )
                _by_user_lang = _dbm.read(
                    f"""SELECT coalesce(actor_email, '(anonymous)') AS actor,
                               {_lang_case} AS lang,
                               count(*)::int AS page_views,
                               to_char(max(ts_utc) AT TIME ZONE 'UTC',
                                       'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS last_seen
                          FROM activity_events
                         WHERE {_where}
                      GROUP BY 1, 2
                      ORDER BY actor, page_views DESC""",
                    (_days,)
                )
                _top_pages = _dbm.read(
                    f"""SELECT detail AS path,
                               count(*)::int AS page_views,
                               count(DISTINCT actor_email)::int AS unique_users,
                               to_char(max(ts_utc) AT TIME ZONE 'UTC',
                                       'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS last_seen
                          FROM activity_events
                         WHERE {_where}
                      GROUP BY 1
                      ORDER BY page_views DESC
                         LIMIT 50""",
                    (_days,)
                )
                _by_user = _dbm.read(
                    f"""SELECT coalesce(actor_email, '(anonymous)') AS actor,
                               count(*)::int AS page_views,
                               count(DISTINCT detail)::int AS unique_pages,
                               to_char(min(ts_utc) AT TIME ZONE 'UTC',
                                       'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS first_seen,
                               to_char(max(ts_utc) AT TIME ZONE 'UTC',
                                       'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS last_seen
                          FROM activity_events
                         WHERE {_where}
                      GROUP BY 1
                      ORDER BY page_views DESC""",
                    (_days,)
                )

                resp = json.dumps({
                    "status": "ok",
                    "window_days":      _days,
                    "by_language":      _by_lang,
                    "by_user_language": _by_user_lang,
                    "top_pages":        _top_pages,
                    "by_user":          _by_user,
                }, default=str).encode()
            except Exception as _e:
                resp = json.dumps({"status":"error","message":str(_e)}).encode()
            self.send_response(200); self.send_header("Content-Type","application/json")
            self.send_header("Content-Length", str(len(resp)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers(); self.wfile.write(resp); return
        # --- end audit GET ---


        # --- SAP Skills API endpoints (no auth required) ---
        if parsed.path == "/sap_skills/api/bw_lake_status":
            try:
                import subprocess as _sp
                _ssh = ["-o", "ConnectTimeout=5", "-o", "StrictHostKeyChecking=no"]
                # Read BWH SAPHANADB password from vault — never hardcode
                _bwh_pwd = ""
                try:
                    _bwh_entries = self._get_vault_credential("bw4hana_hana", "entries")
                    for _e in (_bwh_entries or []):
                        if _e.get("user") == "SAPHANADB" and (_e.get("tenant") == "BWH" or not _e.get("tenant")):
                            _bwh_pwd = _e.get("password", "")
                            break
                except Exception:
                    _bwh_pwd = ""
                # SQL built-in to a shell here-doc pipe — avoid shell escaping pitfalls
                _inner = (
                    "cat <<SQLEOF | /usr/sap/BW4/hdbclient/hdbsql -n localhost:30015 "
                    "-u SAPHANADB -p '" + _bwh_pwd + "' -d BWH -x -quiet -C\n"
                    "SELECT TABLE_NAME||'~'||CATEGORY||'~'||REFRESH_MODE||'~'||"
                    "COALESCE(TO_VARCHAR(LAST_REFRESH_AT,'YYYY-MM-DD HH24:MI:SS'),'')||'~'||"
                    "COALESCE(TO_VARCHAR(LAST_ROW_COUNT),'0')||'~'||"
                    "COALESCE(TO_VARCHAR(LAST_DURATION_MS),'0') "
                    "FROM SAPHANADB.ZBW_META ORDER BY TABLE_NAME;\n"
                    "SQLEOF"
                )
                _r = _sp.run(
                    ["ssh"] + _ssh + ["root@10.128.0.29", "su - bwhadm -c " + '"' + _inner.replace('"', '\\"') + '"'],
                    capture_output=True, text=True, timeout=30)
                _tables = []
                _stale = 0
                _total_rows = 0
                _by_mode = {}
                from datetime import datetime as _dt2, timedelta as _td2
                _cutoff_daily = _dt2.utcnow() - _td2(hours=25)
                _cutoff_hourly = _dt2.utcnow() - _td2(hours=2)
                for _line in _r.stdout.splitlines():
                    _line = _line.strip().strip('"')
                    if not _line or "~" not in _line:
                        continue
                    _parts = _line.split("~")
                    if len(_parts) < 6:
                        continue
                    _tn, _cat, _mode, _lr, _rc, _dur = [_p.strip().strip('"') for _p in _parts[:6]]
                    if not _tn.startswith("ZBW_"):
                        continue
                    try:
                        _rc_int = int(_rc)
                    except Exception:
                        _rc_int = 0
                    _total_rows += _rc_int
                    _by_mode[_mode] = _by_mode.get(_mode, 0) + 1
                    _is_stale = False
                    if _lr and _lr != "?":
                        try:
                            _last = _dt2.strptime(_lr, "%Y-%m-%d %H:%M:%S")
                            if _mode == "full_daily" and _last < _cutoff_daily:
                                _is_stale = True
                            elif _mode in ("full_hourly", "cdc_aedat") and _last < _cutoff_hourly:
                                _is_stale = True
                        except Exception:
                            pass
                    elif _mode in ("full_hourly", "cdc_aedat"):
                        _is_stale = True
                    if _is_stale:
                        _stale += 1
                    _tables.append({
                        "table": _tn, "category": _cat, "mode": _mode,
                        "last_refresh": _lr if _lr and _lr != "?" else None,
                        "rows": _rc_int, "duration_ms": _dur, "stale": _is_stale,
                    })
                self.send_json({
                    "status": "ok",
                    "summary": {
                        "total_tables": len(_tables),
                        "total_rows": _total_rows,
                        "stale_tables": _stale,
                        "by_mode": _by_mode,
                    },
                    "tables": _tables,
                })
            except Exception as e:
                self.send_json({"status": "error", "message": str(e)})
            return

