        # --- ECC Manual Backup Trigger API ---
        if parsed.path == "/sap_skills/api/ecc_trigger_backup":
            try:
                import subprocess
                length = int(self.headers.get("Content-Length", 0))
                body = json.loads(self.rfile.read(length)) if length else {}
                master = body.get("master_password", "")
                import sys
                if "/usr/sap/sap_skills" not in sys.path:
                    sys.path.insert(0, "/usr/sap/sap_skills")
                import vault_manager, importlib
                importlib.reload(vault_manager)
                systems = vault_manager.list_systems(master)
                if systems is None:
                    resp = json.dumps({"status": "error", "message": "Wrong master password"}).encode()
                else:
                    # Block if next scheduled backup is less than 6 hours away
                    from datetime import datetime, timedelta
                    try:
                        from zoneinfo import ZoneInfo
                    except ImportError:
                        from backports.zoneinfo import ZoneInfo
                    server_tz = ZoneInfo("America/Los_Angeles")
                    now = datetime.now(tz=server_tz)
                    days_until_sunday = (6 - now.weekday()) % 7
                    if days_until_sunday == 0 and now.hour >= 7:
                        days_until_sunday = 7
                    next_sunday = (now + timedelta(days=days_until_sunday)).replace(hour=7, minute=0, second=0, microsecond=0)
                    hours_until_next = (next_sunday - now).total_seconds() / 3600
                    if hours_until_next < 6:
                        resp = json.dumps({"status": "error", "message": "Next scheduled backup is in less than 6 hours. Manual backup blocked."}).encode()
                    else:
                        # Run brbackup in background thread (same as crontab script)
                        import threading
                        def run_brbackup():
                            subprocess.run(
                                _local_su("abaadm",
                                          "brbackup -u / -p /oracle/ABA/sapprof/initABA.sap -d disk -t offline_force -c -m all -n 6"),
                                capture_output=True, text=True, timeout=7200
                            )
                        t = threading.Thread(target=run_brbackup, daemon=True)
                        t.start()
                        if _alog: _alog.log_activity("cockpit", "planned", "backup_trigger", "sapidesecc8", "Oracle Backup", "ok", "Oracle Backup backup_trigger via cockpit")
                        resp = json.dumps({"status": "ok", "message": "Offline force backup started. SAP will be stopped during backup."}).encode()
            except Exception as e:
                resp = json.dumps({"status": "error", "message": str(e)}).encode()
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(resp)))
            _send_security_headers(self)
            _send_security_headers(self)
            self.end_headers()

