        # --- HVR Hub Latest Release Check API ---
        if parsed.path == "/sap_skills/api/hvrhub_latest_release":
            try:
                import re as re_mod
                url = "https://fivetran.com/docs/hvr6/release-notes/hvr-62-release-notes"
                req = __import__("urllib.request", fromlist=["Request"]).Request(url, headers={"User-Agent": "Mozilla/5.0"})
                with __import__("urllib.request", fromlist=["urlopen"]).urlopen(req, timeout=15) as resp_http:
                    html = resp_http.read().decode("utf-8", errors="replace")
                # Find the first/latest version pattern like 6.2.5/10
                ver_match = re_mod.search(r'(\d+\.\d+\.\d+/\d+)', html)
                latest = ver_match.group(1) if ver_match else ""
                # Find date near the version (search in nearby context)
                release_date = ""
                if ver_match:
                    nearby = html[ver_match.end():ver_match.end()+500]
                    date_match = re_mod.search(r'(\d{4}-\d{2}-\d{2})', nearby)
                    if date_match:
                        release_date = date_match.group(1)
                resp = json.dumps({
                    "status": "ok",
                    "latest_version": latest,
                    "release_date": release_date,
                    "release_notes_url": "https://fivetran.com/docs/hvr6/release-notes/hvr-62-release-notes"
                }).encode()
            except Exception as e:
                resp = json.dumps({"status": "error", "message": str(e)}).encode()
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(resp)))
            _send_security_headers(self)
            _send_security_headers(self)
            self.end_headers()

            self.wfile.write(resp)
            return

