        # --- HVR Hub Disk Space API ---
        if parsed.path == "/sap_skills/api/hvrhub_disk_space":
            try:
                import subprocess
                result = subprocess.run(
                    ["ssh", "-o", "ConnectTimeout=10", "root@10.128.15.240", "df -h"],
                    capture_output=True, text=True, timeout=15
                )
                # Get NFS exports and active NFS clients (via ss for real internal IPs)
                nfs_result = subprocess.run(
                    ["ssh", "-o", "ConnectTimeout=10", "root@10.128.15.240",
                     "exportfs -v 2>/dev/null | awk '{print $1}' | sort -u; echo '---'; ss -tn state established 2>/dev/null | grep :2049 | awk '{print $4}' | cut -d: -f1 | sort -u; echo '---'; cat /etc/hosts 2>/dev/null"],
                    capture_output=True, text=True, timeout=15
                )
                nfs_exports = set()
                nfs_client_ips = set()
                known_hosts = {}
                if nfs_result.returncode == 0:
                    sections = nfs_result.stdout.strip().split("---")
                    # Section 0: exports
                    if len(sections) >= 1:
                        for line in sections[0].strip().split("\n"):
                            line = line.strip()
                            if line and line.startswith("/"):
                                nfs_exports.add(line)
                    # Section 1: active client IPs from ss
                    if len(sections) >= 2:
                        for line in sections[1].strip().split("\n"):
                            ip = line.strip()
                            if ip and not ip.startswith("127."):
                                nfs_client_ips.add(ip)
                    # Section 2: /etc/hosts for name resolution
                    if len(sections) >= 3:
                        for line in sections[2].strip().split("\n"):
                            line = line.strip()
                            if line and not line.startswith("#"):
                                parts_h = line.split()
                                if len(parts_h) >= 2:
                                    known_hosts[parts_h[0]] = parts_h[1].split(".")[0]
                # All exports share the same NFS client connections
                nfs_clients_by_mount = {}
                for exp in nfs_exports:
                    nfs_clients_by_mount[exp] = nfs_client_ips
                # Get inbound NFS (mounted from other servers)
                fstab_result = subprocess.run(
                    ["ssh", "-o", "ConnectTimeout=10", "root@10.128.15.240",
                     "grep nfs /etc/fstab 2>/dev/null | grep -v ^#"],
                    capture_output=True, text=True, timeout=10
                )
                nfs_mounts = {}
                for line in (fstab_result.stdout.strip().split("\n") if fstab_result.stdout.strip() else []):
                    parts_fstab = line.split()
                    if len(parts_fstab) >= 2:
                        nfs_mounts[parts_fstab[1]] = parts_fstab[0]
                filesystems = []
                for line in result.stdout.strip().split("\n")[1:]:
                    parts = line.split()
                    if len(parts) >= 6 and not parts[5].startswith("/dev/shm") and not parts[5].startswith("/sys") and parts[0] not in ("tmpfs", "devtmpfs"):
                        fs = {
                            "device": parts[0], "size": parts[1], "used": parts[2],
                            "avail": parts[3], "use_pct": parts[4], "mount": parts[5]
                        }
                        mount = parts[5]
                        if mount in nfs_exports:
                            clients = nfs_clients_by_mount.get(mount, set())
                            if clients:
                                names = sorted(set([known_hosts.get(ip, ip) for ip in clients]))
                                fs["nfs_info"] = "NFS exported \u2014 " + str(len(clients)) + " clients: " + ", ".join(names)
                            else:
                                fs["nfs_info"] = "NFS exported (no active clients)"
                        if mount in nfs_mounts:
                            fs["nfs_info"] = "NFS mount from " + nfs_mounts[mount]
                        filesystems.append(fs)
                resp = json.dumps({"status": "ok", "filesystems": filesystems}).encode()
            except Exception as e:
                resp = json.dumps({"status": "error", "message": str(e)}).encode()
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(resp)))
            _send_security_headers(self)
            _send_security_headers(self)
            self.end_headers()

            self.wfile.write(resp)
            return

