        if parsed.path == "/sap_skills/api/s4_otc_filters":
            # JCo path: read VBAK / VBAP via RFC_READ_TABLE.
            # Auto client 100 + ABAP authority via destination user (IDES).
            import subprocess as _sub, json as _json, os as _os, tempfile as _tf
            from collections import Counter as _Counter

            try:
                # Pick the first vault entry — vault order is canonical.
                # This avoids hardcoding any specific SAP user; whoever is first in
                # `sapidess4_s4hana_100.entries` becomes the JCo destination user.
                hana_entries = self._get_vault_credential("sapidess4_s4hana_100", "entries")
                cred = (hana_entries or [None])[0]
                if not cred or not cred.get("password"):
                    raise RuntimeError("S/4HANA RFC credential missing in vault entry sapidess4_s4hana_100")
                rfc_user = cred.get("user", "")
                pwd      = cred.get("password", "")
                # HANA SAPHANADB cred — used to auto-unlock the SAP user if locked
                _hana_v   = self._get_vault_credential("sapidess4_hana", "entries") or []
                _hana_cred = next((e for e in _hana_v
                                  if (e.get("user") or "").upper() == "SAPHANADB"
                                  and (e.get("tenant") or "").upper() == "FIV"), None)
                _hana_pwd  = _hana_cred.get("password", "") if _hana_cred else ""

                def _unlock_sap_user(uname):
                    """Reset USR02.UFLAG=0 for the given SAP user in client 100. Used as
                       a one-shot recovery when JCo logon fails because the user was
                       locked by failed-login counter."""
                    if not uname or not _hana_pwd: return
                    import subprocess as __s
                    sql = ("UPDATE SAPHANADB.USR02 SET UFLAG=0 "
                           "WHERE MANDT='100' AND BNAME=UPPER('" + uname + "');\n")
                    __s.run(["ssh", "-o", "StrictHostKeyChecking=no",
                             "-o", "ConnectTimeout=10", "root@sapidess4",
                             "/usr/sap/S4H/hdbclient/hdbsql -n localhost:30015 "
                             "-u SAPHANADB -p '" + _hana_pwd + "' -d FIV -x -quiet -C"],
                            input=sql, capture_output=True, text=True, timeout=10)

                def _jco(action, table, fields_csv=None, where=None, max_rows=99999, timeout=60):
                    """Run CDSReader Java CLI, return list of pipe-delimited data lines (header stripped)."""
                    workdir = _tf.mkdtemp(prefix="jco_", dir="/tmp")
                    try:
                        # Render destination file
                        with open("/usr/sap/sap_skills/jco/SAP_S4HANA.jcoDestination.template") as f:
                            tmpl = f.read()
                        with open(_os.path.join(workdir, "SAP_S4HANA.jcoDestination"), "w") as f:
                            f.write(tmpl.replace("__SAP_USER__", rfc_user).replace("__SAP_PASSWORD__", pwd))
                        _os.chmod(_os.path.join(workdir, "SAP_S4HANA.jcoDestination"), 0o600)

                        cmd = ["java",
                               "-cp", "/usr/sap/sap_skills/jco/sapjco3.jar:/usr/sap/sap_skills/jco",
                               "-Djava.library.path=/usr/sap/sap_skills/jco",
                               "CDSReader", action, table]
                        if action == "count":
                            if where: cmd.append(where)
                        else:  # read
                            cmd.append(fields_csv or "")
                            cmd.append(where or "-")
                            cmd.append(str(max_rows))
                        p = _sub.run(cmd, capture_output=True, text=True, timeout=timeout, cwd=workdir)
                        if p.returncode != 0 and "incorrect" in (p.stderr or "").lower():
                            _unlock_sap_user(rfc_user)
                            p = _sub.run(cmd, capture_output=True, text=True, timeout=timeout, cwd=workdir)
                        if p.returncode != 0:
                            raise RuntimeError("JCo CLI rc=" + str(p.returncode) + ": " + (p.stderr or "")[:200])
                        return (p.stdout or "").strip().splitlines()
                    finally:
                        try:
                            for fn in _os.listdir(workdir):
                                _os.remove(_os.path.join(workdir, fn))
                            _os.rmdir(workdir)
                        except Exception: pass

                # VKORG list — read VBAK.VKORG, group in python
                vk_lines = _jco("read", "VBAK", "VKORG")
                if vk_lines: vk_lines = vk_lines[1:]  # drop header
                vk_count = _Counter(ln.strip() for ln in vk_lines if ln.strip())
                vkorgs = [{"code": k, "orders": v}
                          for k, v in sorted(vk_count.items(), key=lambda x: -x[1])[:50] if k]

                # WERKS list — read VBAP.WERKS, group in python
                wk_lines = _jco("read", "VBAP", "WERKS")
                if wk_lines: wk_lines = wk_lines[1:]
                wk_count = _Counter(ln.strip() for ln in wk_lines if ln.strip())
                werkses = [{"code": k, "lines": v}
                           for k, v in sorted(wk_count.items(), key=lambda x: -x[1])[:50] if k]

                resp = _json.dumps({"status": "ok", "vkorgs": vkorgs, "werkses": werkses}).encode()
            except Exception as e:
                resp = _json.dumps({"status": "error", "message": str(e)[:200]}).encode()
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Length", str(len(resp)))
            _send_security_headers(self)
            _send_security_headers(self)
            self.end_headers()

            self.wfile.write(resp)
            return

        if parsed.path == "/sap_skills/api/s4_otc_snapshot":
            # JCo path: read raw rows from VBAK/VBFA/ACDOCA + KNA1/MAKT + group in python.
            # Auto client 100 + ABAP authority via destination user (IDES).
            import subprocess as _sub, re as _re, json as _json, os as _os, tempfile as _tf
            from urllib.parse import parse_qs as _parse_qs
            from collections import Counter as _Counter, defaultdict as _dd

            qs = _parse_qs(parsed.query or "")
            def _safe(v):
                if not v or v == "ALL": return None
                v = v[0] if isinstance(v, list) else v
                if not _re.match(r"^[A-Za-z0-9_\-/]{1,10}$", v): return None
                return v.upper()
            vkorg = _safe(qs.get("vkorg"))
            werks = _safe(qs.get("werks"))

            try:
                # Pick the first vault entry — vault order is canonical.
                # This avoids hardcoding any specific SAP user; whoever is first in
                # `sapidess4_s4hana_100.entries` becomes the JCo destination user.
                hana_entries = self._get_vault_credential("sapidess4_s4hana_100", "entries")
                cred = (hana_entries or [None])[0]
                if not cred or not cred.get("password"):
                    raise RuntimeError("S/4HANA RFC credential missing in vault entry sapidess4_s4hana_100")
                rfc_user = cred.get("user", "")
                pwd      = cred.get("password", "")
                # HANA SAPHANADB cred — used to auto-unlock the SAP user if locked
                _hana_v   = self._get_vault_credential("sapidess4_hana", "entries") or []
                _hana_cred = next((e for e in _hana_v
                                  if (e.get("user") or "").upper() == "SAPHANADB"
                                  and (e.get("tenant") or "").upper() == "FIV"), None)
                _hana_pwd  = _hana_cred.get("password", "") if _hana_cred else ""

                def _unlock_sap_user(uname):
                    """Reset USR02.UFLAG=0 for the given SAP user in client 100. Used as
                       a one-shot recovery when JCo logon fails because the user was
                       locked by failed-login counter."""
                    if not uname or not _hana_pwd: return
                    import subprocess as __s
                    sql = ("UPDATE SAPHANADB.USR02 SET UFLAG=0 "
                           "WHERE MANDT='100' AND BNAME=UPPER('" + uname + "');\n")
                    __s.run(["ssh", "-o", "StrictHostKeyChecking=no",
                             "-o", "ConnectTimeout=10", "root@sapidess4",
                             "/usr/sap/S4H/hdbclient/hdbsql -n localhost:30015 "
                             "-u SAPHANADB -p '" + _hana_pwd + "' -d FIV -x -quiet -C"],
                            input=sql, capture_output=True, text=True, timeout=10)

                # Build a single shared workdir for this request
                workdir = _tf.mkdtemp(prefix="jco_snap_", dir="/tmp")
                with open("/usr/sap/sap_skills/jco/SAP_S4HANA.jcoDestination.template") as f: tmpl = f.read()
                with open(_os.path.join(workdir, "SAP_S4HANA.jcoDestination"), "w") as f:
                    f.write(tmpl.replace("__SAP_USER__", rfc_user).replace("__SAP_PASSWORD__", pwd))
                _os.chmod(_os.path.join(workdir, "SAP_S4HANA.jcoDestination"), 0o600)

                def _jco(action, table, fields_csv=None, where=None, max_rows=999999, timeout=120):
                    cmd = ["java",
                           "-cp", "/usr/sap/sap_skills/jco/sapjco3.jar:/usr/sap/sap_skills/jco",
                           "-Djava.library.path=/usr/sap/sap_skills/jco",
                           "CDSReader", action, table]
                    if action == "count":
                        if where: cmd.append(where)
                    else:
                        cmd.append(fields_csv or "")
                        cmd.append(where or "-")
                        cmd.append(str(max_rows))
                    p = _sub.run(cmd, capture_output=True, text=True, timeout=timeout, cwd=workdir)
                    if p.returncode != 0 and "incorrect" in (p.stderr or "").lower():
                        _unlock_sap_user(rfc_user)
                        p = _sub.run(cmd, capture_output=True, text=True, timeout=timeout, cwd=workdir)
                    if p.returncode != 0:
                        raise RuntimeError(table + " rc=" + str(p.returncode) + ": " + (p.stderr or "")[:200])
                    out = (p.stdout or "").strip().splitlines()
                    # count: single number on stdout, no header.  read: header line + data lines.
                    if action == "count":
                        return out
                    return out[1:] if out else []   # strip header

                try:
                    # Build VBAK WHERE clause
                    vbak_where = ("VKORG = '" + vkorg + "'") if vkorg else None
                    # If WERKS filter set, we read distinct VBELNs via VBAP first, then filter VBAK to that set.
                    werks_vbelns = None
                    if werks:
                        vp_lines = _jco("read", "VBAP", "VBELN", "WERKS = '" + werks + "'", 99999)
                        werks_vbelns = set(ln.strip() for ln in vp_lines if ln.strip())

                    # ── 1. Orders + monthly + total value: read VBAK rows ────
                    vbak_lines = _jco("read", "VBAK", "VBELN,ERDAT,KUNNR,NETWR", vbak_where, 999999)
                    vbak_rows = []
                    for ln in vbak_lines:
                        parts = ln.split("|")
                        if len(parts) < 4: continue
                        vbeln = parts[0].strip()
                        if werks_vbelns is not None and vbeln not in werks_vbelns: continue
                        try: netwr = float(parts[3] or 0)
                        except ValueError: netwr = 0.0
                        vbak_rows.append({"vbeln": vbeln, "erdat": parts[1].strip(),
                                          "kunnr": parts[2].strip(), "netwr": netwr})

                    orders_count = len(vbak_rows)
                    total_value  = sum(r["netwr"] for r in vbak_rows)

                    # Monthly aggregation
                    month_acc = _dd(lambda: {"count": 0, "value": 0.0})
                    for r in vbak_rows:
                        if not r["erdat"] or len(r["erdat"]) < 6: continue
                        ym = r["erdat"][:6]
                        month_acc[ym]["count"] += 1
                        month_acc[ym]["value"] += r["netwr"]
                    monthly = [{"month": ym[:4]+"-"+ym[4:6], "count": v["count"], "value": v["value"]}
                               for ym, v in sorted(month_acc.items())]

                    # ── 2. Deliveries + invoices + status: VBFA filtered ────
                    # Build a VBELV-IN list filter only if it would be small. Otherwise skip filter
                    # and post-filter in python.
                    vbeln_set = set(r["vbeln"] for r in vbak_rows)
                    vbfa_lines = _jco("read", "VBFA", "VBELV,VBELN,VBTYP_N",
                                      "VBTYP_N = 'J' OR VBTYP_N = 'M'", 999999)
                    has_J, has_M = set(), set()
                    order_to_bills = {}   # sales order VBELN -> set of billing VBELNs
                    for ln in vbfa_lines:
                        p = ln.split("|")
                        if len(p) < 3: continue
                        v_pred = p[0].strip(); v_succ = p[1].strip(); t = p[2].strip()
                        if v_pred not in vbeln_set: continue
                        if t == 'J':
                            has_J.add(v_pred)
                        elif t == 'M':
                            has_M.add(v_pred)
                            if v_succ:
                                order_to_bills.setdefault(v_pred, set()).add(v_succ)
                    deliveries_count = len(has_J)
                    invoices_count   = len(has_M)

                    # Closed = order has at least one billing whose VBELN appears
                    # as BKPF.XBLNR with BLART='DZ' (incoming payment posted).
                    paid_bills = set()
                    try:
                        bkpf_lines = _jco("read", "BKPF", "XBLNR",
                                          "BLART = 'DZ' AND BUKRS = '1710'", 999999)
                        for ln in bkpf_lines:
                            xb = ln.strip()
                            if xb: paid_bills.add(xb)
                    except Exception:
                        paid_bills = set()
                    closed_set = set()
                    for o, bills in order_to_bills.items():
                        if bills & paid_bills:
                            closed_set.add(o)

                    # Status doughnut
                    open_set      = vbeln_set - has_J
                    delivered_set = has_J - has_M
                    invoiced_set  = has_M - closed_set
                    status_breakdown = [
                        {"name": "open",      "count": len(open_set)},
                        {"name": "delivered", "count": len(delivered_set)},
                        {"name": "invoiced",  "count": len(invoiced_set)},
                        {"name": "closed",    "count": len(closed_set)},
                    ]

                    # ── 3. FI postings — ACDOCA RV/DR/DZ ─────────────────
                    # ACDOCA is SINGLE-CLIENT in S/4 (no MANDT). RFC_READ_TABLE works.
                    # Use count action to avoid shipping every row.
                    acd_lines = _jco("count", "ACDOCA", where="BLART = 'RV' OR BLART = 'DR' OR BLART = 'DZ'")
                    payments_count = int(acd_lines[0].strip()) if acd_lines else 0

                    # ── 4. Top customers — group VBAK by KUNNR, lookup NAME1 from KNA1 ─
                    cust_acc = _dd(lambda: {"orders": 0, "value": 0.0})
                    for r in vbak_rows:
                        if not r["kunnr"]: continue
                        cust_acc[r["kunnr"]]["orders"] += 1
                        cust_acc[r["kunnr"]]["value"]  += r["netwr"]
                    top_cust = sorted(cust_acc.items(), key=lambda x: -x[1]["value"])[:15]
                    top_kunnrs = [k for k, _ in top_cust]
                    # Read full KNA1 in client 100 (≈200 rows) — avoid OR-chain WHERE
                    # that hits RFC_READ_TABLE OPTION_NOT_VALID at >72 char chunks.
                    name_map = {}
                    kna1_lines = _jco("read", "KNA1", "KUNNR,NAME1", None, 99999)
                    for ln in kna1_lines:
                        p = ln.split("|", 1)
                        if len(p) >= 2: name_map[p[0].strip()] = p[1].strip()
                    customers = [{"kunnr": k, "name": name_map.get(k, "(no name)").replace(",", ";"),
                                  "orders": v["orders"], "value": v["value"]}
                                 for k, v in top_cust]

                    # ── 5. Top materials — read VBAP rows for our VBELNs ─
                    # If filter active, build OR clause; else read all VBAP and filter in python.
                    if vbak_where or werks_vbelns is not None:
                        # Trim to manageable filter — use chunks of ORs if needed
                        vbelns_for_vbap = list(vbeln_set)
                    else:
                        vbelns_for_vbap = None  # read all
                    vbap_where = None
                    if vbelns_for_vbap and len(vbelns_for_vbap) <= 200:
                        vbap_where = " OR ".join("VBELN = '" + v + "'" for v in vbelns_for_vbap[:200])
                    vbap_lines = _jco("read", "VBAP", "VBELN,MATNR,KWMENG,NETWR", vbap_where, 999999)
                    mat_acc = _dd(lambda: {"lines": 0, "qty": 0.0, "value": 0.0})
                    for ln in vbap_lines:
                        p = ln.split("|")
                        if len(p) < 4: continue
                        vbeln = p[0].strip()
                        if vbap_where is None and vbeln_set and vbeln not in vbeln_set: continue
                        matnr = p[1].strip()
                        if not matnr: continue
                        try: qty = float(p[2] or 0)
                        except ValueError: qty = 0.0
                        try: nwr = float(p[3] or 0)
                        except ValueError: nwr = 0.0
                        mat_acc[matnr]["lines"] += 1
                        mat_acc[matnr]["qty"]   += qty
                        mat_acc[matnr]["value"] += nwr
                    top_mat = sorted(mat_acc.items(), key=lambda x: -x[1]["value"])[:15]
                    top_matnrs = [k for k, _ in top_mat]
                    # Read English MAKT entries (~3K rows, single short WHERE)
                    matname_map = {}
                    makt_lines = _jco("read", "MAKT", "MATNR,MAKTX", "SPRAS = 'E'", 99999)
                    for ln in makt_lines:
                        p = ln.split("|", 1)
                        if len(p) >= 2: matname_map[p[0].strip()] = p[1].strip()
                    materials = [{"matnr": k, "name": matname_map.get(k, "(no descr)").replace(",", ";"),
                                  "lines": v["lines"], "qty": v["qty"], "value": v["value"]}
                                 for k, v in top_mat]

                    funnel = {
                        "orders":      orders_count,
                        "deliveries":  deliveries_count,
                        "invoices":    invoices_count,
                        "payments":    payments_count,
                        "total_value": total_value,
                    }
                    resp = _json.dumps({
                        "status": "ok",
                        "funnel": funnel,
                        "monthly": monthly,
                        "customers": customers,
                        "materials": materials,
                        "status_breakdown": status_breakdown,
                    }).encode()
                finally:
                    try:
                        for fn in _os.listdir(workdir): _os.remove(_os.path.join(workdir, fn))
                        _os.rmdir(workdir)
                    except Exception: pass
            except Exception as e:
                resp = _json.dumps({"status": "error", "message": str(e)[:200]}).encode()
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Length", str(len(resp)))
            _send_security_headers(self)
            _send_security_headers(self)
            self.end_headers()

            self.wfile.write(resp)
            return

        if parsed.path == "/sap_skills/api/s4_cds_report":
            # JCo path: 28 CDS view reports, each maps to (CDS, fields, group_field, chart_type, label).
            # Reads via RFC_READ_TABLE, groups in Python.
            import subprocess as _sub, json as _json, os as _os, tempfile as _tf, re as _re
            from urllib.parse import parse_qs as _parse_qs
            from collections import Counter as _Counter, defaultdict as _dd

            qs = _parse_qs(parsed.query or "")
            cds = (qs.get("cds", [""])[0] or "").strip()
            if not _re.match(r"^[A-Za-z0-9_]{1,60}$", cds):
                self.send_response(200); self.send_header("Content-Type", "application/json"); self.end_headers()
                self.wfile.write(_json.dumps({"status": "error", "message": "invalid cds name"}).encode())
                return

            # Catalog: cds_name -> (cds_view, fields_csv, group_field|None, value_field|None, chart_type, label)
            #   group_field == None  means "list" report (no grouping, just rows)
            #   value_field          when set, sum it grouped by group_field (top-N by value)
            CATALOG = {
                # ── Sales Order ─────────────────────────────────────────
                "I_SalesOrder":            ("I_SalesOrder",            "SALESORDERTYPE",                          "SALESORDERTYPE",       None,      "doughnut", "By order type"),
                "I_SalesOrderItem":        ("I_SalesOrderItem",        "PRODUCT,NETAMOUNT",                       "PRODUCT",              "NETAMOUNT","bar_h",   "Top 10 materials by net value"),
                "I_SalesOrderScheduleLine":("I_SalesOrderScheduleLine","REQUESTEDDELIVERYDATE",                  "REQUESTEDDELIVERYDATE", None,    "bar_v",   "Schedule lines by requested delivery date (YYYYMM)"),
                "I_SalesOrderPartner":     ("I_SalesOrderPartner",     "PARTNERFUNCTION",                         "PARTNERFUNCTION",      None,      "doughnut", "By partner function"),
                # CDS DDL not queryable via RFC_READ_TABLE on this S/4 instance — falls back to base table PRCD_ELEMENTS (KSCHL = condition type)
                "I_SalesOrderPricingElement":("PRCD_ELEMENTS",          "KSCHL",                                   "KSCHL",                None,      "bar_h",   "Top 10 condition types (KSCHL)"),
                "I_SalesOrderBillingPlanItem":("I_SalesOrderBillingPlanItem","BILLINGPLAN",                       "BILLINGPLAN",          None,      "bar_h",   "Top billing plans"),

                # ── Delivery ─────────────────────────────────────────
                "I_DeliveryDocument":      ("I_DeliveryDocument",      "DELIVERYDOCUMENTTYPE",                    "DELIVERYDOCUMENTTYPE", None,      "doughnut", "By delivery type"),
                "I_DeliveryDocumentItem":  ("I_DeliveryDocumentItem",  "PRODUCT,ACTUALDELIVEREDQTYINBASEUNIT",    "PRODUCT",              "ACTUALDELIVEREDQTYINBASEUNIT", "bar_h", "Top 10 materials by qty delivered"),
                "I_DeliveryDocumentPartner":("I_DeliveryDocumentPartner","PARTNERFUNCTION",                       "PARTNERFUNCTION",      None,      "doughnut", "By partner function on deliveries"),

                # ── Billing ──────────────────────────────────────────
                "I_BillingDocument":       ("I_BillingDocument",       "BILLINGDOCUMENTTYPE",                     "BILLINGDOCUMENTTYPE",  None,      "doughnut", "By billing type"),
                "I_BillingDocumentItem":   ("I_BillingDocumentItem",   "PRODUCT,NETAMOUNT",                       "PRODUCT",              "NETAMOUNT","bar_h",   "Top 10 materials by net invoice value"),
                "I_BillingDocumentPartner":("I_BillingDocumentPartner","PARTNERFUNCTION",                         "PARTNERFUNCTION",      None,      "doughnut", "By partner function on invoices"),

                # ── Material Doc / Goods Issue ───────────────────────
                "I_MaterialDocumentHeader":("I_MaterialDocumentHeader","DOCUMENTDATE",                            "DOCUMENTDATE",         None,      "bar_v",   "Material doc headers by date (YYYYMM bucket)"),
                "I_MaterialDocumentItem":  ("I_MaterialDocumentItem",  "GOODSMOVEMENTTYPE",                       "GOODSMOVEMENTTYPE",    None,      "doughnut", "By movement type"),
                "I_MaterialDocumentHeader_2":("I_MaterialDocumentHeader_2","FISCALYEAR",                          "FISCALYEAR",           None,      "doughnut", "By fiscal year"),
                "I_MaterialDocumentItem_2":("I_MaterialDocumentItem_2","GOODSMOVEMENTTYPE",                       "GOODSMOVEMENTTYPE",    None,      "doughnut", "By movement type"),
                "I_MaterialStock":         ("I_MaterialStock",         "PRODUCT,MATLWRHSESTKQTYINMATLBASEUNIT",   "PRODUCT",              "MATLWRHSESTKQTYINMATLBASEUNIT","bar_h", "Top 10 materials by stock qty"),

                # ── Document Flow ────────────────────────────────────
                # CDS DDLs not queryable via RFC_READ_TABLE — fall back to VBFA (the SD document flow table)
                "I_SDDocumentProcessFlow": ("VBFA",                     "VBTYP_N",                                 "VBTYP_N",              None,      "doughnut", "By next-document category (VBTYP_N)"),
                "I_SDDocumentMultiLevelProcFlow":("VBFA",                "VBTYP_V",                                 "VBTYP_V",              None,      "doughnut", "By predecessor-document category (VBTYP_V)"),
                "I_SalesDocumentSubsqntProcFlow":("I_SalesDocumentSubsqntProcFlow","SUBSEQUENTDOCUMENTCATEGORY",  "SUBSEQUENTDOCUMENTCATEGORY",None, "bar_h",   "Subsequent docs by category"),

                # ── Accounting / Payment ─────────────────────────────
                "I_JournalEntry":          ("I_JournalEntry",          "ACCOUNTINGDOCUMENTTYPE",                  "ACCOUNTINGDOCUMENTTYPE",None,     "doughnut", "By document type"),
                "I_JournalEntryItem":      ("I_JournalEntryItem",      "GLACCOUNT,AMOUNTINCOMPANYCODECURRENCY",   "GLACCOUNT",            "AMOUNTINCOMPANYCODECURRENCY","bar_h", "Top 10 GL accounts by amount"),
                "I_OperationalAcctgDocItem":("I_OperationalAcctgDocItem","DEBITCREDITCODE",                       "DEBITCREDITCODE",      None,      "doughnut", "By debit/credit code"),

                # ── Master Data ──────────────────────────────────────
                "I_Customer":              ("I_Customer",              "COUNTRY",                                 "COUNTRY",              None,      "doughnut", "By country"),
                "I_CustomerCompany":       ("I_CustomerCompany",       "COMPANYCODE",                             "COMPANYCODE",          None,      "doughnut", "By company code"),
                "I_CustomerSalesArea":     ("I_CustomerSalesArea",     "SALESORGANIZATION",                       "SALESORGANIZATION",    None,      "doughnut", "By sales organization"),
                "I_BusinessPartner":       ("I_BusinessPartner",       "BUSINESSPARTNERTYPE",                     "BUSINESSPARTNERTYPE",  None,      "doughnut", "By partner type"),
                "I_Product":               ("I_Product",               "PRODUCTTYPE",                             "PRODUCTTYPE",          None,      "doughnut", "By product type"),
                "I_ProductPlantBasic":     ("I_ProductPlantBasic",     "PLANT",                                   "PLANT",                None,      "bar_h",   "By plant (top 10)"),
                "I_ProductValuation":      ("I_ProductValuation",      "PRODUCT,STOCKVALUE",                      "PRODUCT",              "STOCKVALUE","bar_h",  "Top 10 materials by stock value"),
                "I_ProductSalesDelivery":  ("I_ProductSalesDelivery",  "SALESORGANIZATION",                       "SALESORGANIZATION",    None,      "doughnut", "By sales organization"),
                "I_SalesOrganization":     ("I_SalesOrganization",     "SALESORGANIZATION,COMPANYCODE",           None,                   None,      "list",    "All sales organizations"),
            }

            spec = CATALOG.get(cds)
            if not spec:
                self.send_response(200); self.send_header("Content-Type","application/json"); self.end_headers()
                self.wfile.write(_json.dumps({"status":"error","message":"unknown CDS: "+cds}).encode())
                return
            view, fields_csv, group_field, value_field, chart_type, label = spec

            try:
                # Pick the first vault entry — vault order is canonical.
                # This avoids hardcoding any specific SAP user; whoever is first in
                # `sapidess4_s4hana_100.entries` becomes the JCo destination user.
                hana_entries = self._get_vault_credential("sapidess4_s4hana_100", "entries")
                cred = (hana_entries or [None])[0]
                if not cred or not cred.get("password"):
                    raise RuntimeError("S/4HANA RFC credential missing in vault entry sapidess4_s4hana_100")
                rfc_user = cred.get("user", "")
                pwd      = cred.get("password", "")
                # HANA SAPHANADB cred — used to auto-unlock the SAP user if locked
                _hana_v   = self._get_vault_credential("sapidess4_hana", "entries") or []
                _hana_cred = next((e for e in _hana_v
                                  if (e.get("user") or "").upper() == "SAPHANADB"
                                  and (e.get("tenant") or "").upper() == "FIV"), None)
                _hana_pwd  = _hana_cred.get("password", "") if _hana_cred else ""

                def _unlock_sap_user(uname):
                    """Reset USR02.UFLAG=0 for the given SAP user in client 100. Used as
                       a one-shot recovery when JCo logon fails because the user was
                       locked by failed-login counter."""
                    if not uname or not _hana_pwd: return
                    import subprocess as __s
                    sql = ("UPDATE SAPHANADB.USR02 SET UFLAG=0 "
                           "WHERE MANDT='100' AND BNAME=UPPER('" + uname + "');\n")
                    __s.run(["ssh", "-o", "StrictHostKeyChecking=no",
                             "-o", "ConnectTimeout=10", "root@sapidess4",
                             "/usr/sap/S4H/hdbclient/hdbsql -n localhost:30015 "
                             "-u SAPHANADB -p '" + _hana_pwd + "' -d FIV -x -quiet -C"],
                            input=sql, capture_output=True, text=True, timeout=10)

                workdir = _tf.mkdtemp(prefix="jco_cds_", dir="/tmp")
                with open("/usr/sap/sap_skills/jco/SAP_S4HANA.jcoDestination.template") as f: tmpl = f.read()
                with open(_os.path.join(workdir, "SAP_S4HANA.jcoDestination"), "w") as f:
                    f.write(tmpl.replace("__SAP_USER__", rfc_user).replace("__SAP_PASSWORD__", pwd))
                _os.chmod(_os.path.join(workdir, "SAP_S4HANA.jcoDestination"), 0o600)

                def _jco(action, table, fields=None, where=None, max_rows=999999, timeout=120):
                    cmd = ["java",
                           "-cp", "/usr/sap/sap_skills/jco/sapjco3.jar:/usr/sap/sap_skills/jco",
                           "-Djava.library.path=/usr/sap/sap_skills/jco",
                           "CDSReader", action, table]
                    if action == "count":
                        if where: cmd.append(where)
                    else:
                        cmd.append(fields or "")
                        cmd.append(where or "-")
                        cmd.append(str(max_rows))
                    p = _sub.run(cmd, capture_output=True, text=True, timeout=timeout, cwd=workdir)
                    if p.returncode != 0 and "incorrect" in (p.stderr or "").lower():
                        _unlock_sap_user(rfc_user)
                        p = _sub.run(cmd, capture_output=True, text=True, timeout=timeout, cwd=workdir)
                    if p.returncode != 0:
                        raise RuntimeError("rc="+str(p.returncode)+": "+(p.stderr or "")[:200])
                    out = (p.stdout or "").strip().splitlines()
                    # count returns single number, no header
                    if action == "count":
                        return out
                    return out[1:] if out else []   # strip header for read

                try:
                    # Total row count (separate JCo call — fastest using the narrowest field path)
                    total_lines = _jco("count", view)
                    total = int(total_lines[0].strip()) if total_lines else 0

                    # Read data for chart/list
                    data_lines = _jco("read", view, fields_csv, None, 999999)

                    if chart_type == "list":
                        # Just return raw rows, top 50
                        list_rows = []
                        for ln in data_lines[:50]:
                            list_rows.append([c.strip() for c in ln.split("|")])
                        body = {"status":"ok", "cds":cds, "base_table":view,
                                "total":total,
                                "chart":{"type":"list","label":label,"labels":[],"values":[]},
                                "list":{"rows": list_rows}}
                    else:
                        # Group by group_field, optionally sum value_field
                        if not group_field:
                            raise RuntimeError("spec missing group_field")
                        agg_count = _Counter()
                        agg_value = _dd(float)
                        # Fields order: assume group_field is index 0 (or 0 + value at index 1)
                        for ln in data_lines:
                            p = [c.strip() for c in ln.split("|")]
                            if not p or not p[0]: continue
                            key = p[0]
                            # For date-bucket charts, slice to YYYYMM
                            if "DATE" in group_field and len(key) >= 6: key = key[:6]
                            agg_count[key] += 1
                            if value_field and len(p) > 1:
                                try: agg_value[key] += float(p[1] or 0)
                                except ValueError: pass

                        if value_field:
                            top = sorted(agg_value.items(), key=lambda x: -abs(x[1]))[:12]
                            labels  = [k for k,_ in top]
                            values  = [v for _,v in top]
                        else:
                            top = sorted(agg_count.items(), key=lambda x: -x[1])[:12]
                            labels  = [k for k,_ in top]
                            values  = [v for _,v in top]

                        body = {"status":"ok", "cds":cds, "base_table":view,
                                "total":total,
                                "chart":{"type":chart_type, "label":label,
                                         "labels":labels, "values":values}}
                    resp = _json.dumps(body).encode()
                finally:
                    try:
                        for fn in _os.listdir(workdir): _os.remove(_os.path.join(workdir, fn))
                        _os.rmdir(workdir)
                    except Exception: pass
            except Exception as e:
                resp = _json.dumps({"status":"error","message":str(e)[:200]}).encode()
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Length", str(len(resp)))
            _send_security_headers(self)
            _send_security_headers(self)
            self.end_headers()

            self.wfile.write(resp)
            return

