        if parsed.path == "/sap_skills/api/ecc_system_status":
            try:
                import subprocess
                # Check SAP status via sapcontrol (instance 00, user abaadm)
                sap_result = subprocess.run(
                    _local_su("abaadm", "sapcontrol -nr 00 -function GetProcessList"),
                    capture_output=True, text=True, timeout=15
                )
                sap_active = "GREEN" in sap_result.stdout and "Running" in sap_result.stdout
                green_count = sap_result.stdout.count("GREEN")
                total_lines = [l for l in sap_result.stdout.strip().split("\n") if "," in l and "name" not in l.lower()]
                sap_detail = f"{green_count}/{len(total_lines)} processes running" if sap_active else sap_result.stderr.strip() or "Not reachable"

                # Get SAP kernel version via disp+work -v
                sap_kernel = ""
                try:
                    kern_result = subprocess.run(
                        _local_su("abaadm", "disp+work -v"),
                        capture_output=True, text=True, timeout=15
                    )
                    kern_variant = ""
                    kern_patch = ""
                    for kline in kern_result.stdout.split("\n"):
                        if kline.startswith("kernel make variant"):
                            kern_variant = kline.split()[-1]
                        elif kline.startswith("patch number"):
                            kern_patch = kline.split()[-1]
                    if kern_variant and kern_patch:
                        sap_kernel = kern_variant + " patch " + kern_patch
                except Exception:
                    sap_kernel = ""

                # Check Oracle status via sqlplus (user oraaba) — Phase -1 stdin pipe
                ora_result = subprocess.run(
                    _local_su("oraaba", "sqlplus -s / as sysdba"),
                    input="SET HEADING OFF FEEDBACK OFF PAGESIZE 0\nSELECT STATUS FROM V$INSTANCE;\nEXIT;\n",
                    capture_output=True, text=True, timeout=15
                )
                ora_status = ora_result.stdout.strip()
                ora_active = "OPEN" in ora_status
                ora_detail = "" if ora_active else ora_status or ora_result.stderr.strip() or "Not reachable"

                # Get last successful brbackup from backABA.log (RC=0 at index 6)
                # Server runs in America/Los_Angeles; convert to UTC for client
                from datetime import datetime as _dt, timedelta, timezone
                try:
                    from zoneinfo import ZoneInfo
                except ImportError:
                    from backports.zoneinfo import ZoneInfo
                server_tz = ZoneInfo("America/Los_Angeles")

                ora_last_backup_utc = ""
                try:
                    with open("/oracle/ABA/sapbackup/backABA.log", "r") as bkf:
                        for line in bkf:
                            parts = line.split()
                            if len(parts) > 7 and parts[6] == "0":
                                local_dt = _dt.strptime(parts[4] + " " + parts[5], "%Y-%m-%d %H:%M:%S")
                                local_dt = local_dt.replace(tzinfo=server_tz)
                                ora_last_backup_utc = local_dt.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
                except Exception:
                    ora_last_backup_utc = ""

                # Calculate next brbackup run (cron: 0 7 * * 0 = every Sunday 07:00 server time)
                now = _dt.now(tz=server_tz)
                days_until_sunday = (6 - now.weekday()) % 7
                if days_until_sunday == 0 and now.hour >= 7:
                    days_until_sunday = 7
                next_sunday = (now + timedelta(days=days_until_sunday)).replace(hour=7, minute=0, second=0, microsecond=0)
                next_backup_utc = next_sunday.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

                resp = json.dumps({
                    "status": "ok",
                    "sap": {"active": sap_active, "detail": sap_detail, "kernel": sap_kernel},
                    "oracle": {"active": ora_active, "detail": ora_detail, "last_backup_utc": ora_last_backup_utc, "next_backup_utc": next_backup_utc}
                }).encode()
            except Exception as e:
                resp = json.dumps({"status": "error", "message": str(e)}).encode()
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(resp)))
            _send_security_headers(self)
            _send_security_headers(self)
            self.end_headers()

            self.wfile.write(resp)
            return

